def test_apalache_length_table_coverage_errors_report_source_lines(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    runner = tmp_path / "sumeragi_apalache.sh"
    readme = tmp_path / "README.md"
    cases = {
        "frontier-fast": module.RunnerCase("frontier-fast", "", 2),
        "missing-fast": module.RunnerCase("missing-fast", "", 9),
    }
    length_rows = [
        ("frontier-fast", 2, 3),
        ("orphan-fast", 4, 5),
    ]

    assert module.missing_runner_case_mode_errors(
        cases,
        {"frontier-fast", "missing-fast"},
        {"frontier-fast"},
        runner,
        "Apalache",
        "README Apalache length table",
    ) == [
        f"Apalache runner {runner} case missing-fast at line 9 is missing "
        "from README Apalache length table"
    ]
    assert module.unsupported_command_mode_errors(
        [(mode, line_number) for mode, _length, line_number in length_rows],
        readme,
        "README Apalache length table",
        cases,
        "Apalache",
    ) == [
        f"{readme} README Apalache length table mode orphan-fast at line 5 "
        "is unsupported by the Apalache runner"
    ]


def test_command_modes_uses_requested_runner_regex(tmp_path: Path) -> None:
    module = load_coverage_module()
    script = tmp_path / "commands.sh"
    workflow = tmp_path / "workflow.yml"
    script.write_text(
        "\n".join(
            [
                "# bash scripts/formal/sumeragi_tlc.sh ignored-fast",
                "prose says bash scripts/formal/sumeragi_apalache.sh prose-fast",
                "bash scripts/formal/sumeragi_apalache.sh quorum-fast",
                "run: bash scripts/formal/sumeragi_apalache.sh workflow-fast",
                "bash scripts/formal/sumeragi_tlc.sh frontier-fast",
            ]
        ),
        encoding="utf-8",
    )
    workflow.write_text(
        "\n".join(
            [
                "run: bash scripts/formal/sumeragi_apalache.sh workflow-fast",
                "- run: bash scripts/formal/sumeragi_tlc.sh workflow-tlc-fast",
            ]
        ),
        encoding="utf-8",
    )

    assert module.command_modes(script) == ["quorum-fast"]
    assert module.command_modes(script, module.TLC_COMMAND_RE) == ["frontier-fast"]
    assert module.command_modes(workflow) == ["workflow-fast"]
    assert module.command_modes(workflow, module.TLC_COMMAND_RE) == [
        "workflow-tlc-fast"
    ]


def test_readme_formal_command_block_errors_require_shell_fences(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    readme = tmp_path / "README.md"
    readme.write_text(
        "\n".join(
            [
                "```bash",
                "bash scripts/formal/sumeragi_apalache.sh fast",
                "```",
                "bash scripts/formal/sumeragi_apalache.sh prose-fast",
                "```text",
                "bash scripts/formal/sumeragi_tlc.sh text-fast",
                "```",
                "~~~shell",
                "bash scripts/formal/sumeragi_tlc.sh shell-fast",
                "~~~",
                "```sh",
                "bash scripts/formal/sumeragi_apalache.sh unclosed-fast",
            ]
        ),
        encoding="utf-8",
    )

    assert module.readme_formal_command_block_errors(readme) == [
        f"{readme}:4: README formal runner command must live in a shell "
        "fenced code block: bash scripts/formal/sumeragi_apalache.sh "
        "prose-fast",
        f"{readme}:6: README formal runner command must live in a shell "
        "fenced code block: bash scripts/formal/sumeragi_tlc.sh text-fast",
        f"{readme}:11: README shell fenced code block containing formal "
        "runner commands must be closed",
    ]


def test_active_command_modes_counts_only_direct_active_invocations(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    script = tmp_path / "commands.sh"
    workflow = tmp_path / "workflow.yml"
    script.write_text(
        "\n".join(
            [
                "# bash scripts/formal/sumeragi_apalache.sh commented-fast",
                "description: bash scripts/formal/sumeragi_apalache.sh prose-fast",
                "echo bash scripts/formal/sumeragi_apalache.sh echoed-fast",
                "bash scripts/formal/sumeragi_apalache.sh direct-fast",
                "  - run: bash scripts/formal/sumeragi_apalache.sh workflow-fast",
                "bash scripts/formal/sumeragi_tlc.sh frontier-fast",
            ]
        ),
        encoding="utf-8",
    )
    workflow.write_text(
        "\n".join(
            [
                "run: bash scripts/formal/sumeragi_apalache.sh workflow-fast",
                "- run: bash scripts/formal/sumeragi_tlc.sh workflow-tlc-fast",
            ]
        ),
        encoding="utf-8",
    )

    assert module.active_command_modes(script) == ["direct-fast"]
    assert module.active_command_mode_occurrences(script) == [("direct-fast", 4)]
    assert module.active_command_modes(script, module.TLC_COMMAND_PREFIX) == [
        "frontier-fast"
    ]
    assert module.active_command_mode_occurrences(
        script,
        module.TLC_COMMAND_PREFIX,
    ) == [("frontier-fast", 6)]
    assert module.active_command_modes(workflow) == ["workflow-fast"]
    assert module.active_command_mode_occurrences(workflow) == [
        ("workflow-fast", 1)
    ]
    assert module.active_command_modes(workflow, module.TLC_COMMAND_PREFIX) == [
        "workflow-tlc-fast"
    ]
    assert module.active_command_mode_occurrences(
        workflow,
        module.TLC_COMMAND_PREFIX,
    ) == [("workflow-tlc-fast", 2)]


def test_duplicate_active_command_mode_errors_report_source_lines(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    script = tmp_path / "ci.sh"
    script.write_text(
        "\n".join(
            [
                "bash scripts/formal/sumeragi_apalache.sh frontier-fast",
                "bash scripts/formal/sumeragi_apalache.sh quorum-fast",
                "bash scripts/formal/sumeragi_apalache.sh frontier-fast",
                "# bash scripts/formal/sumeragi_apalache.sh frontier-fast",
                "bash scripts/formal/sumeragi_apalache.sh frontier-fast",
                "bash scripts/formal/sumeragi_tlc.sh frontier-fast",
                "bash scripts/formal/sumeragi_tlc.sh frontier-fast",
            ]
        ),
        encoding="utf-8",
    )

    occurrences = module.active_command_mode_occurrences(script)

    assert occurrences == [
        ("frontier-fast", 1),
        ("quorum-fast", 2),
        ("frontier-fast", 3),
        ("frontier-fast", 5),
    ]
    assert module.duplicate_active_command_mode_errors(
        occurrences,
        script,
        "PR CI Apalache command",
    ) == [
        f"{script} PR CI Apalache command repeats mode frontier-fast at line "
        "3; first declared at line 1; each PR CI Apalache command mode must "
        "be counted once",
        f"{script} PR CI Apalache command repeats mode frontier-fast at line "
        "5; first declared at line 1; each PR CI Apalache command mode must "
        "be counted once",
    ]

    tlc_occurrences = module.active_command_mode_occurrences(
        script,
        module.TLC_COMMAND_PREFIX,
    )

    assert tlc_occurrences == [
        ("frontier-fast", 6),
        ("frontier-fast", 7),
    ]
    assert module.duplicate_active_command_mode_errors(
        tlc_occurrences,
        script,
        "PR CI TLC command",
    ) == [
        f"{script} PR CI TLC command repeats mode frontier-fast at line "
        "7; first declared at line 6; each PR CI TLC command mode must be "
        "counted once",
    ]


def test_active_command_support_occurrence_errors_report_source_lines(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    fast_ci = tmp_path / "fast.sh"
    expected_failure_ci = tmp_path / "expected.sh"
    nightly_workflow = tmp_path / "nightly.yml"
    apalache_cases = {
        "frontier-*": module.RunnerCase(label="frontier-*", body="", line=1),
    }

    surfaces = (
        (
            "PR",
            [
                ("frontier-fast", 2),
                ("orphan-fast", 4),
            ],
            fast_ci,
        ),
        (
            "expected-failure",
            [
                ("bug-orphan", 6),
                ("orphan-fast", 8),
            ],
            expected_failure_ci,
        ),
        (
            "scheduled/manual",
            [
                ("frontier-nightly", 10),
            ],
            nightly_workflow,
        ),
    )

    assert module.active_command_support_occurrence_errors(
        surfaces,
        apalache_cases,
        "Apalache",
    ) == [
        f"bug-orphan is invoked by expected-failure CI at "
        f"{expected_failure_ci}:6 but unsupported by the Apalache runner",
        f"orphan-fast is invoked by PR CI at {fast_ci}:4 but unsupported by "
        "the Apalache runner",
    ]


