    module = load_coverage_module()
    tla = tmp_path / "SumeragiGate.tla"
    missing_target = tmp_path / "SumeragiGate_bug_missing_target.cfg"
    parameterized = tmp_path / "SumeragiGate_bug_parameterized.cfg"
