def test_projected_commit_progress_spec_contract_errors_rejects_module_alias_transition_helper_action_shaped_aggregate_target_body(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    fair_actions = module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS

    cases = (
        ("Direct", "WrappedRbcChunk == Interleaving!Start"),
        ("Identity", "WrappedRbcChunk == TRUE /\\ Interleaving!Start"),
    )
    for suffix, helper_line in cases:
        target = tmp_path / f"SumeragiTransitionHelperAggregate{suffix}Target.tla"
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiTransitionHelperAggregate{suffix}Target ----",
                    "VARIABLES vars",
                    "Start == UNCHANGED vars \\/ TRUE",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateModuleAliasTransitionHelperAggregate{suffix}Target.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=[
                    f"Interleaving == INSTANCE SumeragiTransitionHelperAggregate{suffix}Target",
                ],
                next_lines=[
                    "Next ==",
                    "  \\/ WrappedRbcChunk",
                    *(f"  \\/ {action}" for action in fair_actions),
                    helper_line,
                ],
            ),
            encoding="utf-8",
        )

        assert module.projected_commit_progress_spec_contract_errors(tla) == [
            f"{target}:3 defines projected commit progress transition operator "
            "Start, but direct transition disjunct UNCHANGED vars does not "
            "resolve to a named action-shaped operator; projected commit "
            "progress transition disjuncts must resolve to named zero-arity "
            "action-shaped operators",
            f"{target}:3 defines projected commit progress transition operator "
            "Start, but direct transition disjunct TRUE does not resolve to a "
            "named action-shaped operator; projected commit progress transition "
            "disjuncts must resolve to named zero-arity action-shaped operators",
        ]


