def test_projected_commit_progress_spec_contract_errors_rejects_disjunctive_identity_gated_module_alias_transition_helper_action_shaped_aggregate_target_body(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    fair_actions = module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
    target = (
        tmp_path / "SumeragiDisjunctiveIdentityTransitionHelperAggregateTarget.tla"
    )
    target.write_text(
        "\n".join(
            [
                "---- MODULE SumeragiDisjunctiveIdentityTransitionHelperAggregateTarget ----",
                "VARIABLES vars",
                "Start == UNCHANGED vars \\/ TRUE",
                "====",
            ]
        ),
        encoding="utf-8",
    )
    tla = (
        tmp_path
        / "SumeragiByzantineCommitProjectionGateDisjunctiveIdentityHelperAggregateTarget.tla"
    )
    tla.write_text(
        projected_commit_progress_spec_contract_text(
            module,
            preamble_lines=[
                "Interleaving == INSTANCE SumeragiDisjunctiveIdentityTransitionHelperAggregateTarget",
            ],
            next_lines=[
                "Next ==",
                "  \\/ WrappedRbcChunk",
                *(f"  \\/ {action}" for action in fair_actions),
                "WrappedRbcChunk == FALSE \\/ Interleaving!Start",
            ],
        ),
        encoding="utf-8",
    )

    assert module.projected_commit_progress_spec_contract_errors(tla) == [
        f"{target}:3 defines projected commit progress transition operator "
        "Start, but direct transition disjunct UNCHANGED vars does not resolve "
        "to a named action-shaped operator; projected commit progress "
        "transition disjuncts must resolve to named zero-arity action-shaped "
        "operators",
        f"{target}:3 defines projected commit progress transition operator "
        "Start, but direct transition disjunct TRUE does not resolve to a "
        "named action-shaped operator; projected commit progress transition "
        "disjuncts must resolve to named zero-arity action-shaped operators",
    ]


