def test_projected_commit_progress_spec_contract_errors_rejects_boolean_guarded_module_alias_transition_disjunct_multiple_action_witnesses(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    target = tmp_path / "SumeragiBooleanGuardedTransitionDisjunctAliasTarget.tla"
    target.write_text(
        "\n".join(
            [
                "---- MODULE SumeragiBooleanGuardedTransitionDisjunctAliasTarget ----",
                "VARIABLES vars",
                "Start == UNCHANGED vars",
                "====",
            ]
        ),
        encoding="utf-8",
    )
    fair_action_target = (
        tmp_path / "SumeragiBooleanGuardedTransitionDisjunctFairActionAliasTarget.tla"
    )
    fair_action_target.write_text(
        "\n".join(
            [
                "---- MODULE SumeragiBooleanGuardedTransitionDisjunctFairActionAliasTarget ----",
                "VARIABLES vars",
                "RbcReady == UNCHANGED vars",
                "====",
            ]
        ),
        encoding="utf-8",
    )
    fair_actions = module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
    guarded_target = (
        tmp_path
        / "SumeragiByzantineCommitProjectionGateBooleanGuardedTransitionDisjunct.tla"
    )
    guarded_target.write_text(
        projected_commit_progress_spec_contract_text(
            module,
            preamble_lines=[
                "Interleaving == INSTANCE SumeragiBooleanGuardedTransitionDisjunctAliasTarget",
            ],
            next_lines=[
                "Next ==",
                "  \\/ Guard => Interleaving!Start",
                *(f"  \\/ {action}" for action in fair_actions),
            ],
        ),
        encoding="utf-8",
    )

    next_line = module.tla_operator_signatures(guarded_target)["Next"][0]
    assert module.projected_commit_progress_spec_contract_errors(guarded_target) == [
        f"{guarded_target}:{next_line} defines projected commit progress "
        "transition operator Next, but direct transition disjunct Guard => "
        "Interleaving!Start mixes multiple action witnesses "
        "Interleaving!Start, Start; guarded transition disjuncts must not "
        "mix multiple action witnesses"
    ]

    imported_fair_actions = tuple(
        action
        for action in module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
        if action != "RbcReady"
    )
    guarded_fair_action = (
        tmp_path
        / "SumeragiByzantineCommitProjectionGateBooleanGuardedTransitionDisjunctFairAction.tla"
    )
    guarded_fair_action.write_text(
        projected_commit_progress_spec_contract_text(
            module,
            preamble_lines=[
                "Interleaving == INSTANCE SumeragiBooleanGuardedTransitionDisjunctFairActionAliasTarget",
            ],
            next_lines=[
                "Next ==",
                "  \\/ Guard => Interleaving!RbcReady",
                *(f"  \\/ {action}" for action in imported_fair_actions),
            ],
            action_definition_overrides={
                "RbcReady": "RbcReady == Interleaving!RbcReady",
            },
        ),
        encoding="utf-8",
    )

    next_line = module.tla_operator_signatures(guarded_fair_action)["Next"][0]
    assert (
        module.projected_commit_progress_spec_contract_errors(guarded_fair_action)
        == [
            f"{guarded_fair_action}:{next_line} defines projected commit "
            "progress transition operator Next, but direct transition "
            "disjunct Guard => Interleaving!RbcReady mixes multiple action "
            "witnesses Interleaving!RbcReady, RbcReady; guarded transition "
            "disjuncts must not mix multiple action witnesses"
        ]
    )


