def test_projected_commit_progress_spec_contract_errors_rejects_guarded_and_identity_gated_module_alias_transition_helper_multiple_action_witnesses(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()

    def write_target(name: str) -> Path:
        target = tmp_path / f"{name}.tla"
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE {name} ----",
                    "VARIABLES vars",
                    "Start == UNCHANGED vars",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        return target

    fair_actions = module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
    guarded_target_name = "SumeragiGuardedTransitionHelperAliasWitnessTarget"
    identity_target_name = "SumeragiIdentityTransitionHelperAliasWitnessTarget"
    write_target(guarded_target_name)
    write_target(identity_target_name)
    guarded = (
        tmp_path
        / "SumeragiByzantineCommitProjectionGateGuardedTransitionHelperAliasWitness.tla"
    )
    guarded.write_text(
        projected_commit_progress_spec_contract_text(
            module,
            preamble_lines=[f"Interleaving == INSTANCE {guarded_target_name}"],
            next_lines=[
                "Next ==",
                "  \\/ WrappedRbcChunk",
                *(f"  \\/ {action}" for action in fair_actions),
                "WrappedRbcChunk == Guard => Interleaving!Start",
            ],
        ),
        encoding="utf-8",
    )
    identity = (
        tmp_path
        / "SumeragiByzantineCommitProjectionGateIdentityTransitionHelperAliasWitness.tla"
    )
    identity.write_text(
        projected_commit_progress_spec_contract_text(
            module,
            preamble_lines=[f"Interleaving == INSTANCE {identity_target_name}"],
            next_lines=[
                "Next ==",
                "  \\/ WrappedRbcChunk",
                *(f"  \\/ {action}" for action in fair_actions),
                "WrappedRbcChunk == TRUE /\\ Interleaving!Start",
            ],
        ),
        encoding="utf-8",
    )

    guarded_line = module.tla_operator_signatures(guarded)["WrappedRbcChunk"][0]
    identity_line = module.tla_operator_signatures(identity)["WrappedRbcChunk"][0]
    assert module.projected_commit_progress_spec_contract_errors(guarded) == [
        f"{guarded}:{guarded_line} defines projected commit progress "
        "transition helper WrappedRbcChunk, but direct transition disjunct "
        "Guard => Interleaving!Start mixes multiple action witnesses "
        "Interleaving!Start, Start; guarded transition disjuncts must not "
        "mix multiple action witnesses"
    ]
    assert module.projected_commit_progress_spec_contract_errors(identity) == [
        f"{identity}:{identity_line} defines projected commit progress "
        "transition helper WrappedRbcChunk, but direct transition disjunct "
        "TRUE /\\ Interleaving!Start mixes multiple action witnesses "
        "Interleaving!Start, Start; guarded transition disjuncts must not "
        "mix multiple action witnesses"
    ]


