def test_projected_commit_progress_spec_contract_errors_rejects_module_alias_transition_disjunct_multi_hop_recursive_helper_bad_targets(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    fair_actions = module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS

    def projection_for(target_name: str) -> Path:
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateTransitionDisjunctMultiHop{target_name}.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=[f"Interleaving == INSTANCE {target_name}"],
                next_lines=[
                    "Next ==",
                    "  \\/ Interleaving!Start",
                    *(f"  \\/ {action}" for action in fair_actions),
                ],
            ),
            encoding="utf-8",
        )
        return tla

    def write_imported_target(target_name: str, inner_name: str) -> None:
        target = tmp_path / f"{target_name}.tla"
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE {target_name} ----",
                    "VARIABLES vars",
                    f"Inner == INSTANCE {inner_name}",
                    "Start == HiddenStart",
                    "HiddenStart == Inner!Branch",
                    "====",
                ]
            ),
            encoding="utf-8",
        )

    def write_inner_without_leaf_instance(inner_name: str) -> Path:
        inner = tmp_path / f"{inner_name}.tla"
        inner.write_text(
            "\n".join(
                [
                    f"---- MODULE {inner_name} ----",
                    "VARIABLES vars",
                    "Branch == LocalBranch",
                    "LocalBranch == Leaf!Action",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        return inner

    def write_inner_with_leaf_instance(inner_name: str, leaf_name: str) -> Path:
        inner = tmp_path / f"{inner_name}.tla"
        inner.write_text(
            "\n".join(
                [
                    f"---- MODULE {inner_name} ----",
                    "VARIABLES vars",
                    f"Leaf == INSTANCE {leaf_name}",
                    "Branch == LocalBranch",
                    "LocalBranch == Leaf!Action",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        return inner

    def write_leaf(leaf_name: str, body: str) -> Path:
        leaf = tmp_path / f"{leaf_name}.tla"
        leaf.write_text(
            "\n".join(
                [
                    f"---- MODULE {leaf_name} ----",
                    "VARIABLES vars",
                    body,
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        return leaf

    def write_cyclic_leaf(leaf_name: str) -> Path:
        leaf = tmp_path / f"{leaf_name}.tla"
        leaf.write_text(
            "\n".join(
                [
                    f"---- MODULE {leaf_name} ----",
                    "VARIABLES vars",
                    "Action == HiddenAction",
                    "HiddenAction == Action",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        return leaf

    def write_chain_without_leaf_instance(suffix: str) -> tuple[Path, Path]:
        target_name = f"SumeragiTransitionDisjunctMultiHop{suffix}Target"
        inner_name = f"SumeragiTransitionDisjunctMultiHop{suffix}Inner"
        write_imported_target(target_name, inner_name)
        inner = write_inner_without_leaf_instance(inner_name)
        return projection_for(target_name), inner

    def write_chain_with_leaf(suffix: str, body: str) -> tuple[Path, Path, Path]:
        target_name = f"SumeragiTransitionDisjunctMultiHop{suffix}Target"
        inner_name = f"SumeragiTransitionDisjunctMultiHop{suffix}Inner"
        leaf_name = f"SumeragiTransitionDisjunctMultiHop{suffix}Leaf"
        write_imported_target(target_name, inner_name)
        inner = write_inner_with_leaf_instance(inner_name, leaf_name)
        leaf = write_leaf(leaf_name, body)
        return projection_for(target_name), inner, leaf

    def write_chain_with_cyclic_leaf(suffix: str) -> tuple[Path, Path]:
        target_name = f"SumeragiTransitionDisjunctMultiHop{suffix}Target"
        inner_name = f"SumeragiTransitionDisjunctMultiHop{suffix}Inner"
        leaf_name = f"SumeragiTransitionDisjunctMultiHop{suffix}Leaf"
        write_imported_target(target_name, inner_name)
        write_inner_with_leaf_instance(inner_name, leaf_name)
        leaf = write_cyclic_leaf(leaf_name)
        return projection_for(target_name), leaf

    tla, inner = write_chain_without_leaf_instance("NoInstance")
    assert module.projected_commit_progress_spec_contract_errors(tla) == [
        f"{inner}:4 defines projected commit progress transition helper "
        "LocalBranch, but aliases Leaf!Action without a named INSTANCE "
        "alias Leaf; projected commit progress transition module-alias "
        "helper wrappers must resolve through named local INSTANCE "
        "declarations"
    ]

    target_name = "SumeragiTransitionDisjunctMultiHopMissingTarget"
    inner_name = "SumeragiTransitionDisjunctMultiHopMissingInner"
    leaf_name = "SumeragiTransitionDisjunctMultiHopMissingLeaf"
    write_imported_target(target_name, inner_name)
    inner = write_inner_with_leaf_instance(inner_name, leaf_name)
    missing = tmp_path / f"{leaf_name}.tla"
    tla = projection_for(target_name)
    assert module.projected_commit_progress_spec_contract_errors(tla) == [
        f"{inner}:5 defines projected commit progress transition helper "
        "LocalBranch, but aliases Leaf!Action, but target module "
        f"{missing} does not exist; projected commit progress transition "
        "module-alias helper wrappers must resolve to local modules with "
        "defined zero-arity transition operators"
    ]

    tla, inner, leaf = write_chain_with_leaf("Undefined", "Other == UNCHANGED vars")
    assert module.projected_commit_progress_spec_contract_errors(tla) == [
        f"{inner}:5 defines projected commit progress transition helper "
        f"LocalBranch, but aliases Leaf!Action, but target {leaf} does not "
        "define Action; projected commit progress transition module-alias "
        "helper wrappers must resolve to defined zero-arity transition "
        "operators"
    ]

    tla, inner, leaf = write_chain_with_leaf(
        "Parameterized",
        "Action(value) == UNCHANGED vars",
    )
    assert module.projected_commit_progress_spec_contract_errors(tla) == [
        f"{inner}:5 defines projected commit progress transition helper "
        f"LocalBranch, but aliases Leaf!Action, but target {leaf}:3 has "
        "arity 1; projected commit progress transition module-alias helper "
        "wrappers must resolve to defined zero-arity transition operators"
    ]

    tla, inner, leaf = write_chain_with_leaf("Noninspectable", "Action ==")
    assert module.projected_commit_progress_spec_contract_errors(tla) == [
        f"{inner}:5 defines projected commit progress transition helper "
        "LocalBranch, but aliases Leaf!Action, but target "
        f"{leaf}:3 is not an inspectable single-expression definition; "
        "projected commit progress transition module-alias helper wrappers "
        "must resolve to inspectable transition operators"
    ]

    tla, leaf = write_chain_with_cyclic_leaf("Cycle")
    assert module.projected_commit_progress_spec_contract_errors(tla) == [
        f"{leaf}:3 defines projected commit progress transition helper "
        "Action, but transition helper resolution cycles at Action; "
        "projected commit progress transition helper wrappers must be "
        "acyclic and resolve to inspectable transition operators"
    ]


def test_projected_commit_progress_spec_contract_errors_rejects_false_gated_module_alias_transition_disjunct_target_resolution(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    fair_actions = module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
    root_kind = "projected commit progress"

    def write_module(name: str, lines: list[str]) -> Path:
        path = tmp_path / f"{name}.tla"
        path.write_text(
            "\n".join([f"---- MODULE {name} ----", "VARIABLES vars", *lines, "===="]),
            encoding="utf-8",
        )
        return path

    def write_projection(
        suffix: str,
        alias: str,
        preamble_lines: list[str] | None = None,
    ) -> Path:
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateFalseGated{suffix}.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=preamble_lines or [],
                next_lines=[
                    "Next ==",
                    "  \\/ FALSE",
                    f"  \\/ {alias}",
                    *(f"  \\/ {action}" for action in fair_actions),
                ],
            ),
            encoding="utf-8",
        )
        return tla

    def next_line(tla: Path) -> int:
        return module.tla_operator_signatures(tla)["Next"][0]

    def direct_alias_error(
        tla: Path,
        disjunct: str,
        detail: str,
        requirement: str,
    ) -> str:
        return (
            f"{tla}:{next_line(tla)} defines {root_kind} transition operator "
            f"Next, but direct transition disjunct {disjunct} aliases "
            f"{detail}; {requirement}"
        )

    def errors(tla: Path) -> list[str]:
        return module.projected_commit_progress_spec_contract_errors(tla)

    instance_requirement = (
        f"{root_kind} transition module-alias disjuncts must resolve through "
        "named local INSTANCE declarations"
    )
    missing_instance = write_projection(
        "ModuleAliasTransitionDisjunctWithoutInstance",
        "Missing!Start",
    )
    assert errors(missing_instance) == [
        direct_alias_error(
            missing_instance,
            "Missing!Start",
            "Missing!Start without a named INSTANCE alias Missing",
            instance_requirement,
        )
    ]

    missing_target = tmp_path / "SumeragiFalseGatedProjectedMissingTarget.tla"
    missing_module = write_projection(
        "ModuleAliasTransitionDisjunctMissingTarget",
        "Interleaving!Start",
        ["Interleaving == INSTANCE SumeragiFalseGatedProjectedMissingTarget"],
    )
    local_module_requirement = (
        f"{root_kind} transition module-alias disjuncts must resolve to local "
        "modules with defined zero-arity transition operators"
    )
    assert errors(missing_module) == [
        direct_alias_error(
            missing_module,
            "Interleaving!Start",
            f"Interleaving!Start, but target module {missing_target} does "
            "not exist",
            local_module_requirement,
        )
    ]

    defined_requirement = (
        f"{root_kind} transition module-alias disjuncts must resolve to "
        "defined zero-arity transition operators"
    )
    inspectable_requirement = (
        f"{root_kind} transition module-alias disjuncts must resolve to "
        "inspectable transition operators"
    )
    direct_cases = (
        (
            "Undefined",
            "Other == UNCHANGED vars",
            "does not define Start",
            defined_requirement,
            False,
        ),
        (
            "Parameterized",
            "Start(value) == UNCHANGED vars",
            "has arity 1",
            defined_requirement,
            True,
        ),
        (
            "Noninspectable",
            "Start ==",
            "is not an inspectable single-expression definition",
            inspectable_requirement,
            True,
        ),
    )
    for suffix, target_definition, diagnostic, requirement, include_target_line in (
        direct_cases
    ):
        target_name = f"SumeragiFalseGatedProjected{suffix}DisjunctTarget"
        target = write_module(target_name, [target_definition])
        tla = write_projection(
            f"ModuleAliasTransitionDisjunct{suffix}Target",
            "Interleaving!Start",
            [f"Interleaving == INSTANCE {target_name}"],
        )
        target_label = (
            f"{target}:3 {diagnostic}"
            if include_target_line
            else f"{target} {diagnostic}"
        )

        assert errors(tla) == [
            direct_alias_error(
                tla,
                "Interleaving!Start",
                f"Interleaving!Start, but target {target_label}",
                requirement,
            )
        ]

    cycle_target = write_module(
        "SumeragiFalseGatedProjectedCycleDisjunctTarget",
        [
            "Self == INSTANCE SumeragiFalseGatedProjectedCycleDisjunctTarget",
            "Start == Self!Start",
        ],
    )
    cycle = write_projection(
        "ModuleAliasTransitionDisjunctCycle",
        "Interleaving!Start",
        ["Interleaving == INSTANCE SumeragiFalseGatedProjectedCycleDisjunctTarget"],
    )
    assert errors(cycle) == [
        f"{cycle_target}:4 defines {root_kind} transition helper Start, but "
        "transition helper resolution cycles at Start; projected commit "
        "progress transition helper wrappers must be acyclic and resolve to "
        "inspectable transition operators",
        f"{cycle_target}:4 defines {root_kind} transition operator Start, "
        "but transition alias resolution cycles at Start; projected commit "
        "progress transition aliases must be acyclic and resolve to "
        "inspectable transition operators",
    ]

    onward_target = write_module(
        "SumeragiFalseGatedProjectedOnwardNoInstanceDisjunctTarget",
        ["Start == Inner!HonestPropose"],
    )
    onward = write_projection(
        "ModuleAliasTransitionDisjunctOnwardNoInstance",
        "Interleaving!Start",
        [
            "Interleaving == INSTANCE "
            "SumeragiFalseGatedProjectedOnwardNoInstanceDisjunctTarget"
        ],
    )
    assert errors(onward) == [
        f"{onward_target}:3 defines {root_kind} transition helper Start, but "
        "aliases Inner!HonestPropose without a named INSTANCE alias Inner; "
        "projected commit progress transition module-alias helper wrappers "
        "must resolve through named local INSTANCE declarations",
        f"{onward_target}:3 defines {root_kind} transition operator Start "
        "as Inner!HonestPropose without a named INSTANCE alias Inner; "
        "projected commit progress transition aliases must resolve through "
        "named local INSTANCE declarations",
    ]


def test_projected_commit_progress_spec_contract_errors_rejects_false_gated_module_alias_transition_disjunct_action_shaped_target_body(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    fair_actions = module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
    root_kind = "projected commit progress"

    def write_module(name: str, lines: list[str]) -> Path:
        path = tmp_path / f"{name}.tla"
        path.write_text(
            "\n".join([f"---- MODULE {name} ----", "VARIABLES vars", *lines, "===="]),
            encoding="utf-8",
        )
        return path

    def write_projection(suffix: str, target_name: str) -> Path:
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateFalseGated{suffix}.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=[f"Interleaving == INSTANCE {target_name}"],
                next_lines=[
                    "Next ==",
                    "  \\/ FALSE",
                    "  \\/ Interleaving!Start",
                    *(f"  \\/ {action}" for action in fair_actions),
                ],
            ),
            encoding="utf-8",
        )
        return tla

    non_bare_target = write_module(
        "SumeragiFalseGatedProjectedActionShapedDisjunctTarget",
        [
            "Start == HonestPropose /\\ TRUE /\\ UNCHANGED vars",
            "HonestPropose == UNCHANGED vars",
        ],
    )
    non_bare = write_projection(
        "ModuleAliasTransitionDisjunctActionShapedTarget",
        "SumeragiFalseGatedProjectedActionShapedDisjunctTarget",
    )
    assert module.projected_commit_progress_spec_contract_errors(non_bare) == [
        f"{non_bare_target}:3 defines {root_kind} transition operator "
        "Start, but direct transition disjunct HonestPropose /\\ TRUE /\\ "
        "UNCHANGED vars is not a bare named action or aggregate reference; "
        f"{root_kind} transition disjuncts must stay bare named action or "
        "aggregate references"
    ]

    mixed_target = write_module(
        "SumeragiFalseGatedProjectedMixedWitnessDisjunctTarget",
        [
            "Start == HonestPropose /\\ PrepareVote /\\ UNCHANGED vars",
            "HonestPropose == UNCHANGED vars",
            "PrepareVote == UNCHANGED vars",
        ],
    )
    mixed = write_projection(
        "ModuleAliasTransitionDisjunctMixedWitnessTarget",
        "SumeragiFalseGatedProjectedMixedWitnessDisjunctTarget",
    )
    assert module.projected_commit_progress_spec_contract_errors(mixed) == [
        f"{mixed_target}:3 defines {root_kind} transition operator Start, "
        "but direct transition disjunct HonestPropose /\\ PrepareVote /\\ "
        "UNCHANGED vars mixes multiple action witnesses HonestPropose, "
        "PrepareVote; guarded transition disjuncts must not mix multiple "
        "action witnesses"
    ]

    aggregate_target = write_module(
        "SumeragiFalseGatedProjectedAggregateDisjunctTarget",
        [
            "Start == UNCHANGED vars \\/ TRUE",
        ],
    )
    aggregate = write_projection(
        "ModuleAliasTransitionDisjunctAggregateTarget",
        "SumeragiFalseGatedProjectedAggregateDisjunctTarget",
    )
    assert module.projected_commit_progress_spec_contract_errors(aggregate) == [
        f"{aggregate_target}:3 defines {root_kind} transition operator "
        "Start, but direct transition disjunct UNCHANGED vars does not "
        f"resolve to a named action-shaped operator; {root_kind} transition "
        "disjuncts must resolve to named zero-arity action-shaped operators",
        f"{aggregate_target}:3 defines {root_kind} transition operator "
        "Start, but direct transition disjunct TRUE does not resolve to a "
        f"named action-shaped operator; {root_kind} transition disjuncts "
        "must resolve to named zero-arity action-shaped operators",
    ]


