def test_projected_commit_progress_spec_contract_errors_rejects_false_gated_identity_gated_module_alias_transition_disjunct_imported_fair_action_malformed_target(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    imported_action = "RbcReady"
    other_actions = tuple(
        action
        for action in module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
        if action != imported_action
    )

    def write_target(
        target_name: str,
        lines: list[str] | None,
    ) -> Path:
        target = tmp_path / f"{target_name}.tla"
        if lines is not None:
            target.write_text(
                "\n".join(
                    [
                        f"---- MODULE {target_name} ----",
                        "VARIABLES vars",
                        *lines,
                        "====",
                    ]
                ),
                encoding="utf-8",
            )
        return target

    def write_projection(case_name: str, target_name: str) -> Path:
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateFalseGatedIdentityFairAction{case_name}.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=[f"Interleaving == INSTANCE {target_name}"],
                next_lines=[
                    "Next ==",
                    "  \\/ FALSE",
                    f"  \\/ TRUE /\\ Interleaving!{imported_action}",
                    *(f"  \\/ {action}" for action in other_actions),
                ],
                action_definition_overrides={
                    imported_action: (
                        f"{imported_action} == Interleaving!{imported_action}"
                    ),
                },
            ),
            encoding="utf-8",
        )
        return tla

    def fairness_action_line(tla: Path) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if "WF_vars" in line and imported_action in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {imported_action}")

    def expected_errors(
        tla: Path,
        target_problem: str,
        disjunct_requirement: str,
        fairness_requirement: str,
        *,
        include_reachability_error: bool = False,
    ) -> list[str]:
        signatures = module.tla_operator_signatures(tla)
        definitions = module.tla_single_expression_operator_definitions(tla)
        next_line = signatures["Next"][0]
        fairness_line = definitions["ProjectedCommitProgressFairness"][0]
        action_line = signatures[imported_action][0]
        wf_line = fairness_action_line(tla)
        errors = [
            f"{tla}:{next_line} defines projected commit progress transition "
            "operator Next, but direct transition disjunct TRUE /\\ "
            f"Interleaving!{imported_action} aliases "
            f"Interleaving!{imported_action}, but {target_problem}; "
            "projected commit progress transition module-alias disjuncts "
            f"must resolve to {disjunct_requirement}",
        ]
        if include_reachability_error:
            errors.append(
                f"{tla}:{next_line} defines projected commit progress "
                "transition operator Next, but [][Next]_vars cannot reach "
                f"fair action(s) {imported_action}; projected commit "
                "progress fairness actions must be reachable from the "
                "checked transition closure"
            )
        errors.append(
            f"{tla}:{fairness_line} defines ProjectedCommitProgressFairness, "
            f"but references WF_vars action {imported_action} at line "
            f"{wf_line} whose definition at line {action_line} aliases "
            f"Interleaving!{imported_action}, but {target_problem}; "
            "projected commit progress fairness action aliases must resolve "
            f"to {fairness_requirement}",
        )
        return errors

    missing_target_name = (
        "SumeragiFalseGatedIdentityProjectedFairActionMissingTarget"
    )
    missing_target = write_target(missing_target_name, None)
    missing = write_projection("MissingTarget", missing_target_name)
    assert module.projected_commit_progress_spec_contract_errors(
        missing
    ) == expected_errors(
        missing,
        f"target module {missing_target} does not exist",
        "local modules with defined zero-arity transition operators",
        "local action modules",
        include_reachability_error=True,
    )

    undefined_target_name = (
        "SumeragiFalseGatedIdentityProjectedFairActionUndefinedTarget"
    )
    undefined_target = write_target(
        undefined_target_name,
        ["Other == UNCHANGED vars"],
    )
    undefined = write_projection("UndefinedTarget", undefined_target_name)
    assert module.projected_commit_progress_spec_contract_errors(
        undefined
    ) == expected_errors(
        undefined,
        f"target {undefined_target} does not define {imported_action}",
        "defined zero-arity transition operators",
        "defined zero-arity actions",
    )

    parameterized_target_name = (
        "SumeragiFalseGatedIdentityProjectedFairActionParameterizedTarget"
    )
    parameterized_target = write_target(
        parameterized_target_name,
        [f"{imported_action}(value) == UNCHANGED vars"],
    )
    parameterized_line = module.tla_operator_signatures(parameterized_target)[
        imported_action
    ][0]
    parameterized = write_projection("ParameterizedTarget", parameterized_target_name)
    assert module.projected_commit_progress_spec_contract_errors(
        parameterized
    ) == expected_errors(
        parameterized,
        f"target {parameterized_target}:{parameterized_line} has arity 1",
        "defined zero-arity transition operators",
        "defined zero-arity actions",
    )

    noninspectable_target_name = (
        "SumeragiFalseGatedIdentityProjectedFairActionNoninspectableTarget"
    )
    noninspectable_target = write_target(
        noninspectable_target_name,
        [f"{imported_action} =="],
    )
    noninspectable_line = module.tla_operator_signatures(noninspectable_target)[
        imported_action
    ][0]
    noninspectable = write_projection(
        "NoninspectableTarget",
        noninspectable_target_name,
    )
    assert module.projected_commit_progress_spec_contract_errors(
        noninspectable
    ) == expected_errors(
        noninspectable,
        (
            f"target {noninspectable_target}:{noninspectable_line} is not an "
            "inspectable single-expression definition"
        ),
        "inspectable transition operators",
        "inspectable actions",
    )


