def test_projected_commit_progress_spec_contract_errors_rejects_false_gated_identity_gated_module_alias_transition_disjunct_imported_fair_action_target_body_module_alias_helper_aggregate_branch_variants(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    imported_action = "RbcReady"
    root_kind = "projected commit progress"
    other_actions = tuple(
        action
        for action in module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
        if action != imported_action
    )

    def fairness_action_line(tla: Path) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if "WF_vars" in line and imported_action in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {imported_action}")

    def branch_error(inner: Path, helper_line: int, disjunct: str, kind: str) -> str:
        prefix = (
            f"{inner}:{helper_line} defines {root_kind} transition operator "
            f"HiddenAggregate, but direct transition disjunct {disjunct} "
        )
        if kind == "static":
            return (
                f"{prefix}does not resolve to a named action-shaped operator; "
                f"{root_kind} transition disjuncts must resolve to named "
                "zero-arity action-shaped operators"
            )
        return (
            f"{prefix}contains fairness or temporal syntax; {root_kind} "
            "transition disjuncts must stay single-branch action predicates"
        )

    def assert_module_alias_branch_case(
        label: str,
        use_mid: bool,
        inner_lines: list[str],
        expected_branches: list[tuple[str, str]],
    ) -> None:
        inner = (
            tmp_path
            / f"SumeragiFalseGatedIdentityProjectedFairAction{label}AggregateBranchInner.tla"
        )
        inner.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentityProjectedFairAction{label}AggregateBranchInner ----",
                    "VARIABLES vars",
                    *inner_lines,
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        if use_mid:
            mid = (
                tmp_path
                / f"SumeragiFalseGatedIdentityProjectedFairAction{label}AggregateBranchMid.tla"
            )
            mid.write_text(
                "\n".join(
                    [
                        f"---- MODULE SumeragiFalseGatedIdentityProjectedFairAction{label}AggregateBranchMid ----",
                        "VARIABLES vars",
                        f"Inner == INSTANCE {inner.stem}",
                        "MidHelper == Inner!HiddenAggregate",
                        "====",
                    ]
                ),
                encoding="utf-8",
            )
            target_lines = [
                f"Mid == INSTANCE {mid.stem}",
                f"{imported_action} == HiddenHelper",
                "HiddenHelper == Mid!MidHelper",
            ]
        else:
            target_lines = [
                f"Inner == INSTANCE {inner.stem}",
                f"{imported_action} == HiddenHelper",
                "HiddenHelper == Inner!HiddenAggregate",
            ]
        target = (
            tmp_path
            / f"SumeragiFalseGatedIdentityProjectedFairAction{label}AggregateBranchTarget.tla"
        )
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentityProjectedFairAction{label}AggregateBranchTarget ----",
                    "VARIABLES vars",
                    *target_lines,
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateFalseGatedIdentityFairAction{label}AggregateBranchTarget.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=[f"Interleaving == INSTANCE {target.stem}"],
                next_lines=[
                    "Next ==",
                    "  \\/ FALSE",
                    f"  \\/ TRUE /\\ Interleaving!{imported_action}",
                    *(f"  \\/ {action}" for action in other_actions),
                ],
                action_definition_overrides={
                    imported_action: f"{imported_action} == Interleaving!{imported_action}",
                },
            ),
            encoding="utf-8",
        )

        inner_definitions = module.tla_single_expression_operator_definitions(inner)
        target_signatures = module.tla_operator_signatures(target)
        definitions = module.tla_single_expression_operator_definitions(tla)
        signatures = module.tla_operator_signatures(tla)
        target_line = target_signatures[imported_action][0]
        helper_line = inner_definitions["HiddenAggregate"][0]
        fairness_line = definitions["ProjectedCommitProgressFairness"][0]
        action_line = signatures[imported_action][0]
        wf_line = fairness_action_line(tla)
        assert module.projected_commit_progress_spec_contract_errors(tla) == [
            *[
                branch_error(inner, helper_line, disjunct, kind)
                for disjunct, kind in expected_branches
            ],
            f"{tla}:{fairness_line} defines ProjectedCommitProgressFairness, "
            f"but references WF_vars action {imported_action} at line {wf_line} "
            f"whose definition at line {action_line} aliases "
            f"Interleaving!{imported_action}, but target {target}:"
            f"{target_line} is not action-shaped; {root_kind} fairness action "
            "aliases must resolve to transition definitions that mention "
            "next-state updates or UNCHANGED",
        ]

    for suffix, use_mid in (("ModuleAlias", False), ("MultiHopModuleAlias", True)):
        assert_module_alias_branch_case(
            f"{suffix}AllStatic",
            use_mid,
            ["HiddenAggregate == UNCHANGED vars \\/ TRUE"],
            [("UNCHANGED vars", "static"), ("TRUE", "static")],
        )
        assert_module_alias_branch_case(
            f"{suffix}ActionStatic",
            use_mid,
            [
                "HiddenAggregate == UNCHANGED vars \\/ HiddenReady",
                "HiddenReady == UNCHANGED vars",
            ],
            [("UNCHANGED vars", "static")],
        )
        assert_module_alias_branch_case(
            f"{suffix}StaticTemporal",
            use_mid,
            [
                "HiddenAggregate == UNCHANGED vars \\/ WF_vars(HiddenReady)",
                "HiddenReady == UNCHANGED vars",
            ],
            [("UNCHANGED vars", "static"), ("WF_vars(HiddenReady)", "temporal")],
        )


