def test_projected_commit_progress_spec_contract_errors_rejects_false_gated_identity_gated_module_alias_transition_disjunct_imported_fair_action_target_body_invalid_helper_references(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    imported_action = "RbcReady"
    root_kind = "projected commit progress"
    other_actions = tuple(
        action
        for action in module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
        if action != imported_action
    )

    def write_target(suffix: str, lines: list[str]) -> Path:
        target = (
            tmp_path
            / f"SumeragiFalseGatedIdentityProjectedFairActionInvalidHelper{suffix}Target.tla"
        )
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentityProjectedFairActionInvalidHelper{suffix}Target ----",
                    "VARIABLES vars",
                    *lines,
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        return target

    def write_projection(suffix: str, target_name: str) -> Path:
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateFalseGatedIdentityFairActionInvalidHelper{suffix}.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=[f"Interleaving == INSTANCE {target_name}"],
                next_lines=[
                    "Next ==",
                    "  \\/ FALSE",
                    f"  \\/ TRUE /\\ Interleaving!{imported_action}",
                    *(f"  \\/ {action}" for action in other_actions),
                ],
                action_definition_overrides={
                    imported_action: f"{imported_action} == Interleaving!{imported_action}",
                },
            ),
            encoding="utf-8",
        )
        return tla

    def fairness_action_line(tla: Path) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if "WF_vars" in line and imported_action in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {imported_action}")

    direct_target = write_target(
        "Direct",
        [
            f"{imported_action} == UNCHANGED vars /\\ ParameterizedHelper /\\ OpaqueHelper",
            "ParameterizedHelper(peer) == UNCHANGED vars",
            "OpaqueHelper ==",
        ],
    )
    direct_tla = write_projection("Direct", direct_target.stem)
    direct_definitions = module.tla_single_expression_operator_definitions(direct_tla)
    direct_signatures = module.tla_operator_signatures(direct_tla)
    direct_target_signatures = module.tla_operator_signatures(direct_target)
    direct_fairness_line = direct_definitions["ProjectedCommitProgressFairness"][0]
    direct_next_line = direct_signatures["Next"][0]
    direct_action_line = direct_signatures[imported_action][0]
    direct_target_line = direct_target_signatures[imported_action][0]
    direct_parameterized_line = direct_target_signatures["ParameterizedHelper"][0]
    direct_opaque_line = direct_target_signatures["OpaqueHelper"][0]
    direct_wf_line = fairness_action_line(direct_tla)
    assert module.projected_commit_progress_spec_contract_errors(direct_tla) == [
        f"{direct_tla}:{direct_next_line} defines {root_kind} transition "
        "operator Next, but direct transition disjunct FALSE does not resolve "
        f"to a named action-shaped operator; {root_kind} transition disjuncts "
        "must resolve to named zero-arity action-shaped operators",
        f"{direct_tla}:{direct_next_line} defines {root_kind} transition "
        "operator Next, but direct transition disjunct TRUE /\\ "
        f"Interleaving!{imported_action} mixes multiple action witnesses "
        f"Interleaving!{imported_action}, {imported_action}; guarded "
        "transition disjuncts must not mix multiple action witnesses",
        f"{direct_tla}:{direct_fairness_line} defines "
        "ProjectedCommitProgressFairness, but references WF_vars action "
        f"{imported_action} at line {direct_wf_line} whose definition at "
        f"line {direct_action_line} aliases Interleaving!{imported_action}, "
        f"but target {direct_target}:{direct_target_line} reaches helper "
        f"ParameterizedHelper at {direct_target}:{direct_parameterized_line}, "
        f"but helper has arity 1; {root_kind} fairness action aliases must "
        "resolve helper references to defined zero-arity helper definitions",
        f"{direct_tla}:{direct_fairness_line} defines "
        "ProjectedCommitProgressFairness, but references WF_vars action "
        f"{imported_action} at line {direct_wf_line} whose definition at "
        f"line {direct_action_line} aliases Interleaving!{imported_action}, "
        f"but target {direct_target}:{direct_target_line} reaches helper "
        f"OpaqueHelper at {direct_target}:{direct_opaque_line}, but helper "
        f"is not an inspectable single-expression definition; {root_kind} "
        "fairness action aliases must resolve helper references to "
        "inspectable helper definitions",
    ]

    boolean_target = write_target(
        "Boolean",
        [
            f"{imported_action} == UNCHANGED vars \\/ Wrapped",
            "Wrapped == FALSE \\/ ParameterizedHelper",
            "ParameterizedHelper(peer) == UNCHANGED vars",
        ],
    )
    boolean_tla = write_projection("Boolean", boolean_target.stem)
    boolean_definitions = module.tla_single_expression_operator_definitions(
        boolean_tla
    )
    boolean_signatures = module.tla_operator_signatures(boolean_tla)
    boolean_target_signatures = module.tla_operator_signatures(boolean_target)
    boolean_fairness_line = boolean_definitions["ProjectedCommitProgressFairness"][0]
    boolean_action_line = boolean_signatures[imported_action][0]
    boolean_target_line = boolean_target_signatures[imported_action][0]
    boolean_wrapper_line = boolean_target_signatures["Wrapped"][0]
    boolean_parameterized_line = boolean_target_signatures["ParameterizedHelper"][0]
    boolean_wf_line = fairness_action_line(boolean_tla)
    assert module.projected_commit_progress_spec_contract_errors(boolean_tla) == [
        f"{boolean_target}:{boolean_target_line} defines {root_kind} "
        f"transition operator {imported_action}, but direct transition "
        "disjunct UNCHANGED vars does not resolve to a named action-shaped "
        f"operator; {root_kind} transition disjuncts must resolve to named "
        "zero-arity action-shaped operators",
        f"{boolean_target}:{boolean_wrapper_line} defines {root_kind} "
        "transition operator Wrapped, but direct transition disjunct FALSE "
        f"does not resolve to a named action-shaped operator; {root_kind} "
        "transition disjuncts must resolve to named zero-arity action-shaped "
        "operators",
        f"{boolean_target}:{boolean_wrapper_line} defines {root_kind} "
        "transition operator Wrapped, but direct transition disjunct "
        "ParameterizedHelper does not resolve to a named action-shaped "
        f"operator; {root_kind} transition disjuncts must resolve to named "
        "zero-arity action-shaped operators",
        f"{boolean_tla}:{boolean_fairness_line} defines "
        "ProjectedCommitProgressFairness, but references WF_vars action "
        f"{imported_action} at line {boolean_wf_line} whose definition at "
        f"line {boolean_action_line} aliases Interleaving!{imported_action}, "
        f"but target {boolean_target}:{boolean_target_line} reaches helper "
        f"ParameterizedHelper at {boolean_target}:"
        f"{boolean_parameterized_line}, but helper has arity 1; {root_kind} "
        "fairness action aliases must resolve helper references to defined "
        "zero-arity helper definitions",
    ]


def test_projected_commit_progress_spec_contract_errors_rejects_false_gated_identity_gated_module_alias_transition_disjunct_imported_fair_action_target_body_module_alias_helper_wrapper_cycles(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    imported_action = "RbcReady"
    root_kind = "projected commit progress"
    other_actions = tuple(
        action
        for action in module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
        if action != imported_action
    )

    def fairness_action_line(tla: Path) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if "WF_vars" in line and imported_action in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {imported_action}")

    def assert_module_alias_cycle_case(label: str, use_mid: bool) -> None:
        inner = (
            tmp_path
            / f"SumeragiFalseGatedIdentityProjectedFairAction{label}HelperCycleInner.tla"
        )
        inner.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentityProjectedFairAction{label}HelperCycleInner ----",
                    "VARIABLES vars",
                    "Tail == Tail",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        if use_mid:
            mid = (
                tmp_path
                / f"SumeragiFalseGatedIdentityProjectedFairAction{label}HelperCycleMid.tla"
            )
            mid.write_text(
                "\n".join(
                    [
                        f"---- MODULE SumeragiFalseGatedIdentityProjectedFairAction{label}HelperCycleMid ----",
                        "VARIABLES vars",
                        f"Inner == INSTANCE {inner.stem}",
                        "MidHelper == Inner!Tail",
                        "====",
                    ]
                ),
                encoding="utf-8",
            )
            target_lines = [
                f"Mid == INSTANCE {mid.stem}",
                f"{imported_action} == HiddenHelper",
                "HiddenHelper == Mid!MidHelper",
            ]
        else:
            target_lines = [
                f"Inner == INSTANCE {inner.stem}",
                f"{imported_action} == HiddenHelper",
                "HiddenHelper == Inner!Tail",
            ]
        target = (
            tmp_path
            / f"SumeragiFalseGatedIdentityProjectedFairAction{label}HelperCycleTarget.tla"
        )
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentityProjectedFairAction{label}HelperCycleTarget ----",
                    "VARIABLES vars",
                    *target_lines,
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateFalseGatedIdentityFairAction{label}HelperCycleTarget.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=[f"Interleaving == INSTANCE {target.stem}"],
                next_lines=[
                    "Next ==",
                    "  \\/ FALSE",
                    f"  \\/ TRUE /\\ Interleaving!{imported_action}",
                    *(f"  \\/ {action}" for action in other_actions),
                ],
                action_definition_overrides={
                    imported_action: f"{imported_action} == Interleaving!{imported_action}",
                },
            ),
            encoding="utf-8",
        )

        inner_definitions = module.tla_single_expression_operator_definitions(inner)
        target_signatures = module.tla_operator_signatures(target)
        definitions = module.tla_single_expression_operator_definitions(tla)
        signatures = module.tla_operator_signatures(tla)
        target_line = target_signatures[imported_action][0]
        helper_line = inner_definitions["Tail"][0]
        fairness_line = definitions["ProjectedCommitProgressFairness"][0]
        action_line = signatures[imported_action][0]
        wf_line = fairness_action_line(tla)
        assert module.projected_commit_progress_spec_contract_errors(tla) == [
            f"{inner}:{helper_line} defines {root_kind} transition helper "
            "Tail, but transition helper resolution cycles at Tail; "
            f"{root_kind} transition helper wrappers must be acyclic and "
            "resolve to inspectable transition operators",
            f"{tla}:{fairness_line} defines ProjectedCommitProgressFairness, "
            f"but references WF_vars action {imported_action} at line {wf_line} "
            f"whose definition at line {action_line} aliases "
            f"Interleaving!{imported_action}, but target {target}:"
            f"{target_line} reaches helper Tail at {inner}:{helper_line}, "
            "but fairness action alias helper alias resolution cycles at "
            f"Tail; {root_kind} fairness action aliases must resolve through "
            "acyclic helper aliases",
            f"{tla}:{fairness_line} defines ProjectedCommitProgressFairness, "
            f"but references WF_vars action {imported_action} at line {wf_line} "
            f"whose definition at line {action_line} aliases "
            f"Interleaving!{imported_action}, but target {target}:"
            f"{target_line} is not action-shaped; {root_kind} fairness action "
            "aliases must resolve to transition definitions that mention "
            "next-state updates or UNCHANGED",
        ]

    assert_module_alias_cycle_case("ModuleAlias", False)
    assert_module_alias_cycle_case("MultiHopModuleAlias", True)


def test_projected_commit_progress_spec_contract_errors_rejects_false_gated_identity_gated_module_alias_transition_disjunct_imported_fair_action_target_body_module_alias_helper_resolution_errors(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    imported_action = "RbcReady"
    root_kind = "projected commit progress"
    other_actions = tuple(
        action
        for action in module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
        if action != imported_action
    )

    def fairness_action_line(tla: Path) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if "WF_vars" in line and imported_action in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {imported_action}")

    def assert_resolution_case(
        label: str,
        target_lines: list[str],
        inner_lines: list[str] | None,
        transition_problem,
        fairness_problem,
    ) -> None:
        inner = None
        inner_name = f"SumeragiFalseGatedIdentityProjectedFairAction{label}ResolutionInner"
        if inner_lines is not None:
            inner = tmp_path / f"{inner_name}.tla"
            inner.write_text(
                "\n".join(
                    [
                        f"---- MODULE {inner_name} ----",
                        "VARIABLES vars",
                        *inner_lines,
                        "====",
                    ]
                ),
                encoding="utf-8",
            )
        target = (
            tmp_path
            / f"SumeragiFalseGatedIdentityProjectedFairAction{label}ResolutionTarget.tla"
        )
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentityProjectedFairAction{label}ResolutionTarget ----",
                    "VARIABLES vars",
                    *(
                        line.format(inner=inner_name)
                        for line in target_lines
                    ),
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateFalseGatedIdentityFairAction{label}ResolutionTarget.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=[f"Interleaving == INSTANCE {target.stem}"],
                next_lines=[
                    "Next ==",
                    "  \\/ FALSE",
                    f"  \\/ TRUE /\\ Interleaving!{imported_action}",
                    *(f"  \\/ {action}" for action in other_actions),
                ],
                action_definition_overrides={
                    imported_action: f"{imported_action} == Interleaving!{imported_action}",
                },
            ),
            encoding="utf-8",
        )

        target_signatures = module.tla_operator_signatures(target)
        target_definitions = module.tla_single_expression_operator_definitions(target)
        definitions = module.tla_single_expression_operator_definitions(tla)
        signatures = module.tla_operator_signatures(tla)
        target_line = target_signatures[imported_action][0]
        helper_line = target_definitions["HiddenHelper"][0]
        fairness_line = definitions["ProjectedCommitProgressFairness"][0]
        action_line = signatures[imported_action][0]
        wf_line = fairness_action_line(tla)
        assert module.projected_commit_progress_spec_contract_errors(tla) == [
            f"{target}:{helper_line} defines {root_kind} transition helper "
            f"HiddenHelper, but {transition_problem(target, inner)}",
            f"{tla}:{fairness_line} defines ProjectedCommitProgressFairness, "
            f"but references WF_vars action {imported_action} at line {wf_line} "
            f"whose definition at line {action_line} aliases "
            f"Interleaving!{imported_action}, but target {target}:"
            f"{target_line} {fairness_problem(target, helper_line, inner)}",
            f"{tla}:{fairness_line} defines ProjectedCommitProgressFairness, "
            f"but references WF_vars action {imported_action} at line {wf_line} "
            f"whose definition at line {action_line} aliases "
            f"Interleaving!{imported_action}, but target {target}:"
            f"{target_line} is not action-shaped; {root_kind} fairness action "
            "aliases must resolve to transition definitions that mention "
            "next-state updates or UNCHANGED",
        ]

    assert_resolution_case(
        "MissingInstance",
        [
            f"{imported_action} == HiddenHelper",
            "HiddenHelper == Missing!Tail",
        ],
        None,
        lambda _target, _inner: (
            "aliases Missing!Tail without a named INSTANCE alias Missing; "
            f"{root_kind} transition module-alias helper wrappers must "
            "resolve through named local INSTANCE declarations"
        ),
        lambda target, helper_line, _inner: (
            f"reaches helper HiddenHelper at {target}:{helper_line} aliasing "
            "Missing!Tail without a named INSTANCE alias Missing; "
            f"{root_kind} fairness action aliases must resolve helper aliases "
            "through named local INSTANCE declarations"
        ),
    )
    assert_resolution_case(
        "MissingModule",
        [
            "Inner == INSTANCE MissingTailModule",
            f"{imported_action} == HiddenHelper",
            "HiddenHelper == Inner!Tail",
        ],
        None,
        lambda target, _inner: (
            "aliases Inner!Tail, but target module "
            f"{target.with_name('MissingTailModule.tla')} does not exist; "
            f"{root_kind} transition module-alias helper wrappers must "
            "resolve to local modules with defined zero-arity transition "
            "operators"
        ),
        lambda target, helper_line, _inner: (
            f"reaches helper HiddenHelper at {target}:{helper_line} aliasing "
            "Inner!Tail, but target module "
            f"{target.with_name('MissingTailModule.tla')} does not exist; "
            f"{root_kind} fairness action aliases must resolve helper aliases "
            "to local action modules"
        ),
    )
    assert_resolution_case(
        "Undefined",
        [
            "Inner == INSTANCE {inner}",
            f"{imported_action} == HiddenHelper",
            "HiddenHelper == Inner!Tail",
        ],
        ["Other == UNCHANGED vars"],
        lambda _target, inner: (
            f"aliases Inner!Tail, but target {inner} does not define Tail; "
            f"{root_kind} transition module-alias helper wrappers must "
            "resolve to defined zero-arity transition operators"
        ),
        lambda target, helper_line, inner: (
            f"reaches helper HiddenHelper at {target}:{helper_line} aliasing "
            f"Inner!Tail, but target {inner} does not define Tail; "
            f"{root_kind} fairness action aliases must resolve helper aliases "
            "to defined zero-arity actions"
        ),
    )
    assert_resolution_case(
        "Parameterized",
        [
            "Inner == INSTANCE {inner}",
            f"{imported_action} == HiddenHelper",
            "HiddenHelper == Inner!Tail",
        ],
        ["Tail(value) == UNCHANGED vars"],
        lambda _target, inner: (
            f"aliases Inner!Tail, but target {inner}:3 has arity 1; "
            f"{root_kind} transition module-alias helper wrappers must "
            "resolve to defined zero-arity transition operators"
        ),
        lambda target, helper_line, inner: (
            f"reaches helper HiddenHelper at {target}:{helper_line} aliasing "
            f"Inner!Tail, but target {inner}:3 has arity 1; {root_kind} "
            "fairness action aliases must resolve helper aliases to defined "
            "zero-arity actions"
        ),
    )
    assert_resolution_case(
        "Noninspectable",
        [
            "Inner == INSTANCE {inner}",
            f"{imported_action} == HiddenHelper",
            "HiddenHelper == Inner!Tail",
        ],
        ["Tail =="],
        lambda _target, inner: (
            f"aliases Inner!Tail, but target {inner}:3 is not an inspectable "
            f"single-expression definition; {root_kind} transition "
            "module-alias helper wrappers must resolve to inspectable "
            "transition operators"
        ),
        lambda _target, _helper_line, inner: (
            f"reaches helper Tail at {inner}:3, but helper is not an "
            "inspectable single-expression definition; "
            f"{root_kind} fairness action aliases must resolve helper-alias "
            "helper references to inspectable helper definitions"
        ),
    )


