def test_projected_commit_progress_spec_contract_errors_rejects_false_gated_identity_gated_module_alias_transition_disjunct_imported_fair_action_target_body_boolean_helper_alias_direct_and_transitive_fair_action(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()
    imported_action = "RbcReady"
    nested_action = "RbcDeliver"
    root_kind = "projected commit progress"
    other_actions = tuple(
        action
        for action in module.SUMERAGI_PROJECTED_COMMIT_PROGRESS_FAIRNESS_ACTIONS
        if action != imported_action
    )

    def fairness_action_line(tla: Path) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if "WF_vars" in line and imported_action in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {imported_action}")

    def assert_boolean_helper_alias_fair_action_case(
        variant: str,
        transitive: bool,
    ) -> None:
        if transitive:
            leaf = (
                tmp_path
                / f"SumeragiFalseGatedIdentityProjectedFairActionBooleanHelperAlias{variant}FairActionLeaf.tla"
            )
            leaf.write_text(
                "\n".join(
                    [
                        f"---- MODULE SumeragiFalseGatedIdentityProjectedFairActionBooleanHelperAlias{variant}FairActionLeaf ----",
                        "VARIABLES vars",
                        f"{nested_action} == UNCHANGED vars",
                        "====",
                    ]
                ),
                encoding="utf-8",
            )
            inner = (
                tmp_path
                / f"SumeragiFalseGatedIdentityProjectedFairActionBooleanHelperAlias{variant}FairActionInner.tla"
            )
            inner.write_text(
                "\n".join(
                    [
                        f"---- MODULE SumeragiFalseGatedIdentityProjectedFairActionBooleanHelperAlias{variant}FairActionInner ----",
                        "VARIABLES vars",
                        f"Leaf == INSTANCE {leaf.stem}",
                        f"Tail == Leaf!{nested_action}",
                        "====",
                    ]
                ),
                encoding="utf-8",
            )
            helper_alias = "Inner!Tail"
        else:
            inner = (
                tmp_path
                / f"SumeragiFalseGatedIdentityProjectedFairActionBooleanHelperAlias{variant}FairActionInner.tla"
            )
            inner.write_text(
                "\n".join(
                    [
                        f"---- MODULE SumeragiFalseGatedIdentityProjectedFairActionBooleanHelperAlias{variant}FairActionInner ----",
                        "VARIABLES vars",
                        f"{nested_action} == UNCHANGED vars",
                        "====",
                    ]
                ),
                encoding="utf-8",
            )
            helper_alias = f"Inner!{nested_action}"

        target = (
            tmp_path
            / f"SumeragiFalseGatedIdentityProjectedFairActionBooleanHelperAlias{variant}FairActionTarget.tla"
        )
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentityProjectedFairActionBooleanHelperAlias{variant}FairActionTarget ----",
                    "VARIABLES vars",
                    f"Inner == INSTANCE {inner.stem}",
                    f"{imported_action} == UNCHANGED vars \\/ HiddenHelper",
                    f"HiddenHelper == {helper_alias}",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        tla = (
            tmp_path
            / f"SumeragiByzantineCommitProjectionGateFalseGatedIdentityFairActionBooleanHelperAlias{variant}FairActionTarget.tla"
        )
        tla.write_text(
            projected_commit_progress_spec_contract_text(
                module,
                preamble_lines=[f"Interleaving == INSTANCE {target.stem}"],
                next_lines=[
                    "Next ==",
                    "  \\/ FALSE",
                    f"  \\/ TRUE /\\ Interleaving!{imported_action}",
                    *(f"  \\/ {action}" for action in other_actions),
                ],
                action_definition_overrides={
                    imported_action: f"{imported_action} == Interleaving!{imported_action}",
                },
            ),
            encoding="utf-8",
        )

        target_signatures = module.tla_operator_signatures(target)
        definitions = module.tla_single_expression_operator_definitions(tla)
        signatures = module.tla_operator_signatures(tla)
        target_line = target_signatures[imported_action][0]
        fairness_line = definitions["ProjectedCommitProgressFairness"][0]
        action_line = signatures[imported_action][0]
        wf_line = fairness_action_line(tla)
        assert module.projected_commit_progress_spec_contract_errors(tla) == [
            f"{target}:{target_line} defines {root_kind} transition "
            f"operator {imported_action}, but direct transition disjunct "
            f"UNCHANGED vars does not resolve to a named action-shaped "
            f"operator; {root_kind} transition disjuncts must resolve to "
            "named zero-arity action-shaped operators",
            f"{tla}:{fairness_line} defines ProjectedCommitProgressFairness, "
            f"but references WF_vars action {imported_action} at line "
            f"{wf_line} whose definition at line {action_line} aliases "
            f"Interleaving!{imported_action}, but target {target}:"
            f"{target_line} reaches fair action(s) {nested_action} through "
            f"helper alias(es); {root_kind} fairness action aliases must not "
            "resolve through helper aliases that compose other fair actions",
        ]

    assert_boolean_helper_alias_fair_action_case("Direct", transitive=False)
    assert_boolean_helper_alias_fair_action_case("Transitive", transitive=True)


