def test_source_commit_progress_and_top_level_commit_spec_contract_errors_reject_boolean_operand_fairness_action_helper_alias_resolution_errors(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()

    def write_case(
        role: str,
        variant: str,
        hidden_action: str,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
    ) -> tuple[Path, Path | None, Path]:
        target_name = f"Sumeragi{role}BooleanHelperAlias{variant}Target"
        target = tmp_path / f"{target_name}.tla"
        wrapper = f"Wrapped{role}FairAction"
        preamble_lines: list[str]
        if variant == "WithoutInstance":
            preamble_lines = [f"{wrapper} == Missing!{hidden_action}"]
            target_path: Path | None = None
        else:
            preamble_lines = [
                f"Interleaving == INSTANCE {target_name}",
                f"{wrapper} == Interleaving!{hidden_action}",
            ]
            target_path = target
            if variant == "Undefined":
                target.write_text(
                    "\n".join(
                        [
                            f"---- MODULE {target_name} ----",
                            "VARIABLES vars",
                            "Other == UNCHANGED vars",
                            "====",
                        ]
                    ),
                    encoding="utf-8",
                )
            elif variant == "Parameterized":
                target.write_text(
                    "\n".join(
                        [
                            f"---- MODULE {target_name} ----",
                            "VARIABLES vars",
                            f"{hidden_action}(value) == UNCHANGED vars",
                            "====",
                        ]
                    ),
                    encoding="utf-8",
                )
            elif variant == "Noninspectable":
                target.write_text(
                    "\n".join(
                        [
                            f"---- MODULE {target_name} ----",
                            "VARIABLES vars",
                            f"{hidden_action} ==",
                            "====",
                        ]
                    ),
                    encoding="utf-8",
                )

        tla = tmp_path / f"Sumeragi{role}BooleanHelperAlias{variant}.tla"
        tla.write_text(
            commit_progress_spec_contract_text(
                spec_operator=spec_operator,
                fairness_operator=fairness_operator,
                next_closure=next_closure,
                fairness_actions=fairness_actions,
                preamble_lines=preamble_lines,
                action_definition_overrides={
                    fairness_actions[0]: f"{fairness_actions[0]} == UNCHANGED vars \\/ {wrapper}",
                },
            ),
            encoding="utf-8",
        )
        return tla, target_path, target

    def expected_error(
        tla: Path,
        target_path: Path | None,
        expected_target: Path,
        role: str,
        variant: str,
        fairness_operator: str,
        action: str,
        hidden_action: str,
        root_kind: str,
    ) -> str:
        definitions = module.tla_single_expression_operator_definitions(tla)
        signatures = module.tla_operator_signatures(tla)
        wrapper = f"Wrapped{role}FairAction"
        fairness_line = definitions[fairness_operator][0]
        action_line = signatures[action][0]
        wrapper_line = signatures[wrapper][0]
        prefix = (
            f"{tla}:{fairness_line} defines {fairness_operator}, but "
            f"references WF_vars action {action} at line {fairness_line} "
            f"whose definition at line {action_line} reaches helper "
        )

        if variant == "WithoutInstance":
            return (
                prefix
                + f"{wrapper} at {tla}:{wrapper_line} aliasing "
                f"Missing!{hidden_action} without a named INSTANCE alias "
                f"Missing; {root_kind} fairness action helper aliases must "
                "resolve through named local INSTANCE declarations"
            )
        if variant == "Missing":
            return (
                prefix
                + f"{wrapper} at {tla}:{wrapper_line} aliasing "
                f"Interleaving!{hidden_action}, but target module "
                f"{expected_target} does not exist; {root_kind} fairness "
                "action helper aliases must resolve to local action modules"
            )
        if variant == "Undefined":
            return (
                prefix
                + f"{wrapper} at {tla}:{wrapper_line} aliasing "
                f"Interleaving!{hidden_action}, but target {expected_target} "
                f"does not define {hidden_action}; {root_kind} fairness "
                "action helper aliases must resolve to defined zero-arity "
                "actions"
            )

        assert target_path is not None
        target_signatures = module.tla_operator_signatures(target_path)
        target_line = target_signatures[hidden_action][0]
        if variant == "Parameterized":
            return (
                prefix
                + f"{wrapper} at {tla}:{wrapper_line} aliasing "
                f"Interleaving!{hidden_action}, but target {target_path}:"
                f"{target_line} has arity 1; {root_kind} fairness action "
                "helper aliases must resolve to defined zero-arity actions"
            )
        return (
            prefix
            + f"{hidden_action} at {target_path}:{target_line}, but helper "
            f"is not an inspectable single-expression definition; {root_kind} "
            "fairness action helper aliases must resolve imported helper "
            "references to inspectable helper definitions"
        )

    (
        _source_module_path,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    ) = module.SUMERAGI_SOURCE_COMMIT_PROGRESS_SPEC_CONTRACTS[2]
    (
        _top_module_path,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    ) = module.SUMERAGI_TOP_LEVEL_COMMIT_SPEC_CONTRACTS[0]

    for variant in (
        "WithoutInstance",
        "Missing",
        "Undefined",
        "Parameterized",
        "Noninspectable",
    ):
        source_case = write_case(
            "Source",
            variant,
            "HiddenSourceFairAction",
            source_spec,
            source_fairness,
            source_next_closure,
            source_actions,
        )
        top_case = write_case(
            "Top",
            variant,
            "HiddenTopFairAction",
            top_spec,
            top_fairness,
            top_next_closure,
            top_actions,
        )

        assert module.source_commit_progress_spec_contract_errors(
            (
                (
                    source_case[0],
                    source_spec,
                    source_fairness,
                    source_next_closure,
                    source_actions,
                    source_root_kind,
                ),
            )
        ) == [
            expected_error(
                *source_case,
                "Source",
                variant,
                source_fairness,
                source_actions[0],
                "HiddenSourceFairAction",
                source_root_kind,
            )
        ]
        assert module.top_level_commit_spec_contract_errors(
            (
                (
                    top_case[0],
                    top_spec,
                    top_fairness,
                    top_next_closure,
                    top_actions,
                    top_root_kind,
                ),
            )
        ) == [
            expected_error(
                *top_case,
                "Top",
                variant,
                top_fairness,
                top_actions[0],
                "HiddenTopFairAction",
                top_root_kind,
            )
        ]


