def test_source_commit_progress_and_top_level_commit_spec_contract_errors_reject_fairness_action_alias_module_alias_operands_imported_invalid_helper_references(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()

    def write_case(
        role: str,
        variant: str,
        hidden_action: str,
        connector: str,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
    ) -> tuple[Path, Path, Path]:
        leaf = tmp_path / f"Sumeragi{role}{variant}DirectInvalidHelperLeaf.tla"
        leaf.write_text(
            "\n".join(
                [
                    f"---- MODULE Sumeragi{role}{variant}DirectInvalidHelperLeaf ----",
                    "VARIABLES vars",
                    "Tail == ParameterizedHelper /\\ OpaqueHelper",
                    "ParameterizedHelper(peer) == UNCHANGED vars",
                    "OpaqueHelper ==",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        target = tmp_path / f"Sumeragi{role}{variant}DirectInvalidHelperTarget.tla"
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE Sumeragi{role}{variant}DirectInvalidHelperTarget ----",
                    "VARIABLES vars",
                    f"Nested == INSTANCE Sumeragi{role}{variant}DirectInvalidHelperLeaf",
                    f"{hidden_action} == UNCHANGED vars {connector} Nested!Tail",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        tla = tmp_path / f"Sumeragi{role}{variant}DirectInvalidHelper.tla"
        tla.write_text(
            commit_progress_spec_contract_text(
                spec_operator=spec_operator,
                fairness_operator=fairness_operator,
                next_closure=next_closure,
                fairness_actions=fairness_actions,
                preamble_lines=[
                    f"Interleaving == INSTANCE Sumeragi{role}{variant}DirectInvalidHelperTarget",
                ],
                action_definition_overrides={
                    fairness_actions[0]: f"{fairness_actions[0]} == Interleaving!{hidden_action}",
                },
            ),
            encoding="utf-8",
        )
        return tla, target, leaf

    def expected_errors(
        tla: Path,
        target: Path,
        leaf: Path,
        fairness_operator: str,
        action: str,
        hidden_action: str,
        root_kind: str,
        operand_kind: str,
        requirement_label: str,
    ) -> list[str]:
        definitions = module.tla_single_expression_operator_definitions(tla)
        signatures = module.tla_operator_signatures(tla)
        target_definitions = module.tla_single_expression_operator_definitions(target)
        leaf_signatures = module.tla_operator_signatures(leaf)
        fairness_line = definitions[fairness_operator][0]
        action_line = signatures[action][0]
        target_line = target_definitions[hidden_action][0]
        parameterized_line = leaf_signatures["ParameterizedHelper"][0]
        opaque_line = leaf_signatures["OpaqueHelper"][0]

        return [
            f"{tla}:{fairness_line} defines {fairness_operator}, but "
            f"references WF_vars action {action} at line {fairness_line} "
            f"whose definition at line {action_line} aliases "
            f"Interleaving!{hidden_action}, but target {target}:"
            f"{target_line} uses {operand_kind} Nested!Tail, but helper "
            f"ParameterizedHelper at {leaf}:{parameterized_line} has arity "
            f"1; {root_kind} fairness action aliases must resolve "
            f"{requirement_label} to defined zero-arity actions",
            f"{tla}:{fairness_line} defines {fairness_operator}, but "
            f"references WF_vars action {action} at line {fairness_line} "
            f"whose definition at line {action_line} aliases "
            f"Interleaving!{hidden_action}, but target {target}:"
            f"{target_line} uses {operand_kind} Nested!Tail, but helper "
            f"OpaqueHelper at {leaf}:{opaque_line} is not an inspectable "
            f"single-expression definition; {root_kind} fairness action "
            f"aliases must resolve {requirement_label} to inspectable action "
            "definitions",
        ]

    (
        _source_module_path,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    ) = module.SUMERAGI_SOURCE_COMMIT_PROGRESS_SPEC_CONTRACTS[2]
    (
        _top_module_path,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    ) = module.SUMERAGI_TOP_LEVEL_COMMIT_SPEC_CONTRACTS[0]

    for variant, connector, operand_kind, requirement_label in (
        ("Conjunct", "/\\", "module-alias conjunct", "module-alias conjuncts"),
        (
            "Boolean",
            "\\/",
            "module-alias boolean operand",
            "module-alias boolean operands",
        ),
    ):
        source, source_target, source_leaf = write_case(
            "Source",
            variant,
            "HiddenSourceFairAction",
            connector,
            source_spec,
            source_fairness,
            source_next_closure,
            source_actions,
        )
        top, top_target, top_leaf = write_case(
            "Top",
            variant,
            "HiddenTopFairAction",
            connector,
            top_spec,
            top_fairness,
            top_next_closure,
            top_actions,
        )

        assert module.source_commit_progress_spec_contract_errors(
            (
                (
                    source,
                    source_spec,
                    source_fairness,
                    source_next_closure,
                    source_actions,
                    source_root_kind,
                ),
            )
        ) == expected_errors(
            source,
            source_target,
            source_leaf,
            source_fairness,
            source_actions[0],
            "HiddenSourceFairAction",
            source_root_kind,
            operand_kind,
            requirement_label,
        )
        assert module.top_level_commit_spec_contract_errors(
            (
                (
                    top,
                    top_spec,
                    top_fairness,
                    top_next_closure,
                    top_actions,
                    top_root_kind,
                ),
            )
        ) == expected_errors(
            top,
            top_target,
            top_leaf,
            top_fairness,
            top_actions[0],
            "HiddenTopFairAction",
            top_root_kind,
            operand_kind,
            requirement_label,
        )


def test_source_commit_progress_and_top_level_commit_spec_contract_errors_reject_fairness_action_alias_module_alias_operand_helper_alias_resolution_errors(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()

    def write_case(
        role: str,
        variant: str,
        hidden_action: str,
        connector: str,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
    ) -> tuple[Path, Path, Path, Path, Path, Path, Path]:
        undefined = tmp_path / f"Sumeragi{role}{variant}OperandAliasUndefined.tla"
        undefined.write_text(
            "\n".join(
                [
                    f"---- MODULE Sumeragi{role}{variant}OperandAliasUndefined ----",
                    "VARIABLES vars",
                    "Other == UNCHANGED vars",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        arity = tmp_path / f"Sumeragi{role}{variant}OperandAliasArity.tla"
        arity.write_text(
            "\n".join(
                [
                    f"---- MODULE Sumeragi{role}{variant}OperandAliasArity ----",
                    "VARIABLES vars",
                    "Action(peer) == UNCHANGED vars",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        opaque = tmp_path / f"Sumeragi{role}{variant}OperandAliasOpaque.tla"
        opaque.write_text(
            "\n".join(
                [
                    f"---- MODULE Sumeragi{role}{variant}OperandAliasOpaque ----",
                    "VARIABLES vars",
                    "Action ==",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        missing = tmp_path / f"Sumeragi{role}{variant}OperandAliasMissing.tla"
        leaf = tmp_path / f"Sumeragi{role}{variant}OperandAliasLeaf.tla"
        leaf.write_text(
            "\n".join(
                [
                    f"---- MODULE Sumeragi{role}{variant}OperandAliasLeaf ----",
                    "VARIABLES vars",
                    f"Absent == INSTANCE Sumeragi{role}{variant}OperandAliasMissing",
                    f"Undefined == INSTANCE Sumeragi{role}{variant}OperandAliasUndefined",
                    f"Arity == INSTANCE Sumeragi{role}{variant}OperandAliasArity",
                    f"Opaque == INSTANCE Sumeragi{role}{variant}OperandAliasOpaque",
                    "Tail == Missing!Action /\\ Absent!Action /\\ Undefined!Action /\\ Arity!Action /\\ Opaque!Action",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
