def test_source_commit_progress_and_top_level_commit_spec_contract_errors_reject_init_module_helper_target_guards(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()

    def write_target(target_name: str, body: str) -> Path:
        target = tmp_path / f"{target_name}.tla"
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE {target_name} ----",
                    "VARIABLES vars",
                    body,
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        return target

    def write_contract(
        filename: str,
        *,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
        target_name: str,
    ) -> Path:
        contract = tmp_path / filename
        contract.write_text(
            commit_progress_spec_contract_text(
                spec_operator=spec_operator,
                fairness_operator=fairness_operator,
                next_closure=next_closure,
                fairness_actions=fairness_actions,
                init_lines=[
                    f"Inner == INSTANCE {target_name}",
                    "GoodInit == vars = vars",
                    "Init == GoodInit /\\ Inner!HiddenInit",
                ],
            ),
            encoding="utf-8",
        )
        return contract

    (
        _source_module_path,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    ) = module.SUMERAGI_SOURCE_COMMIT_PROGRESS_SPEC_CONTRACTS[0]
    source_missing_target_name = "SumeragiSourceInitModuleHelperMissingTarget"
    source_missing_target = tmp_path / f"{source_missing_target_name}.tla"
    source_missing = write_contract(
        "SumeragiDirectDeliveredFirstCorridorGateModuleHelperMissingTarget.tla",
        spec_operator=source_spec,
        fairness_operator=source_fairness,
        next_closure=source_next_closure,
        fairness_actions=source_actions,
        target_name=source_missing_target_name,
    )
    source_undefined_target_name = "SumeragiSourceInitModuleHelperUndefinedTarget"
    source_undefined_target = write_target(
        source_undefined_target_name,
        "Other == TRUE",
    )
    source_undefined = write_contract(
        "SumeragiDirectDeliveredFirstCorridorGateModuleHelperUndefinedTarget.tla",
        spec_operator=source_spec,
        fairness_operator=source_fairness,
        next_closure=source_next_closure,
        fairness_actions=source_actions,
        target_name=source_undefined_target_name,
    )
    source_parameterized_target_name = (
        "SumeragiSourceInitModuleHelperParameterizedTarget"
    )
    source_parameterized_target = write_target(
        source_parameterized_target_name,
        "HiddenInit(value) == TRUE",
    )
    source_parameterized = write_contract(
        "SumeragiDirectDeliveredFirstCorridorGateModuleHelperParameterizedTarget.tla",
        spec_operator=source_spec,
        fairness_operator=source_fairness,
        next_closure=source_next_closure,
        fairness_actions=source_actions,
        target_name=source_parameterized_target_name,
    )

    (
        _top_module_path,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    ) = module.SUMERAGI_TOP_LEVEL_COMMIT_SPEC_CONTRACTS[0]
    top_missing_target_name = "SumeragiTopInitModuleHelperMissingTarget"
    top_missing_target = tmp_path / f"{top_missing_target_name}.tla"
    top_missing = write_contract(
        "SumeragiModuleHelperMissingTarget.tla",
        spec_operator=top_spec,
        fairness_operator=top_fairness,
        next_closure=top_next_closure,
        fairness_actions=top_actions,
        target_name=top_missing_target_name,
    )
    undefined_target_name = "SumeragiTopInitModuleHelperUndefinedTarget"
    undefined_target = write_target(undefined_target_name, "Other == TRUE")
    undefined = write_contract(
        "SumeragiModuleHelperUndefinedTarget.tla",
        spec_operator=top_spec,
        fairness_operator=top_fairness,
        next_closure=top_next_closure,
        fairness_actions=top_actions,
        target_name=undefined_target_name,
    )

    parameterized_target_name = "SumeragiTopInitModuleHelperParameterizedTarget"
    parameterized_target = write_target(
        parameterized_target_name,
        "HiddenInit(value) == TRUE",
    )
    parameterized = write_contract(
        "SumeragiModuleHelperParameterizedTarget.tla",
        spec_operator=top_spec,
        fairness_operator=top_fairness,
        next_closure=top_next_closure,
        fairness_actions=top_actions,
        target_name=parameterized_target_name,
    )

    source_missing_init_line = module.tla_operator_signatures(source_missing)["Init"][
        0
    ]
    source_undefined_init_line = module.tla_operator_signatures(source_undefined)[
        "Init"
    ][0]
    source_parameterized_init_line = module.tla_operator_signatures(
        source_parameterized
    )["Init"][0]
    source_parameterized_target_hidden_init_line = module.tla_operator_signatures(
        source_parameterized_target
    )["HiddenInit"][0]
    top_missing_init_line = module.tla_operator_signatures(top_missing)["Init"][0]
    undefined_init_line = module.tla_operator_signatures(undefined)["Init"][0]
    parameterized_init_line = module.tla_operator_signatures(parameterized)["Init"][0]
    parameterized_target_hidden_init_line = module.tla_operator_signatures(
        parameterized_target
    )["HiddenInit"][0]
    assert module.source_commit_progress_spec_contract_errors(
        (
            (
                source_missing,
                source_spec,
                source_fairness,
                source_next_closure,
                source_actions,
                source_root_kind,
            ),
        )
    ) == [
        f"{source_missing}:{source_missing_init_line} defines "
        f"{source_root_kind} init operator Init, but "
        f"module helper Inner!HiddenInit targets missing module "
        f"{source_missing_target}; {source_root_kind} init module-alias "
        "helpers must resolve to local modules"
    ]
    assert module.source_commit_progress_spec_contract_errors(
        (
            (
                source_undefined,
                source_spec,
                source_fairness,
                source_next_closure,
                source_actions,
                source_root_kind,
            ),
        )
    ) == [
        f"{source_undefined}:{source_undefined_init_line} defines "
        f"{source_root_kind} init operator Init, but module helper "
        f"Inner!HiddenInit target {source_undefined_target} does not define "
        f"HiddenInit; {source_root_kind} init module-alias helpers must "
        "resolve to defined zero-arity initial-state predicates"
    ]
    assert module.source_commit_progress_spec_contract_errors(
        (
            (
                source_parameterized,
                source_spec,
                source_fairness,
                source_next_closure,
                source_actions,
                source_root_kind,
            ),
        )
    ) == [
        f"{source_parameterized}:{source_parameterized_init_line} defines "
        f"{source_root_kind} init operator Init, but module helper "
        f"Inner!HiddenInit target {source_parameterized_target}:"
        f"{source_parameterized_target_hidden_init_line} has arity 1; "
        f"{source_root_kind} init module-alias helpers must resolve to "
        "defined zero-arity initial-state predicates"
    ]
    assert module.top_level_commit_spec_contract_errors(
        (
            (
                top_missing,
                top_spec,
                top_fairness,
                top_next_closure,
                top_actions,
                top_root_kind,
            ),
        )
    ) == [
        f"{top_missing}:{top_missing_init_line} defines {top_root_kind} init "
        "operator Init, but module helper Inner!HiddenInit targets missing "
        f"module {top_missing_target}; {top_root_kind} init module-alias "
        "helpers must resolve to local modules"
    ]
    assert module.top_level_commit_spec_contract_errors(
        (
            (
                undefined,
                top_spec,
                top_fairness,
                top_next_closure,
                top_actions,
                top_root_kind,
            ),
        )
    ) == [
        f"{undefined}:{undefined_init_line} defines {top_root_kind} init "
        "operator Init, but module helper Inner!HiddenInit target "
        f"{undefined_target} does not define HiddenInit; {top_root_kind} init "
        "module-alias helpers must resolve to defined zero-arity "
        "initial-state predicates"
    ]
    assert module.top_level_commit_spec_contract_errors(
        (
            (
                parameterized,
                top_spec,
                top_fairness,
                top_next_closure,
                top_actions,
                top_root_kind,
            ),
        )
    ) == [
        f"{parameterized}:{parameterized_init_line} defines {top_root_kind} "
        "init operator Init, but module helper Inner!HiddenInit target "
        f"{parameterized_target}:{parameterized_target_hidden_init_line} has "
        f"arity 1; {top_root_kind} init module-alias helpers must resolve to "
        "defined zero-arity initial-state predicates"
    ]


