    source_parameterized_target_name = (
        "SumeragiSourceImportedInitNestedModuleTargetHelperAliasOnwardParameterizedTarget"
    )
    source_parameterized_inner_name = (
        "SumeragiSourceImportedInitNestedModuleTargetHelperAliasOnwardParameterizedInner"
    )
