    top_identity_target_name = "SumeragiTopIdentityHelperMixedImportedAction"
    write_imported_action_module(top_guarded_target_name)
    write_imported_action_module(top_identity_target_name)
    top_guarded = tmp_path / "SumeragiGuardedModuleAliasHelperMixedActionNext.tla"
    top_guarded.write_text(
        commit_progress_spec_contract_text(
            spec_operator=top_spec,
            fairness_operator=top_fairness,
            next_closure=top_next_closure,
            fairness_actions=top_actions,
            preamble_lines=[f"Interleaving == INSTANCE {top_guarded_target_name}"],
            next_lines=[
                f"{top_next_operator} ==",
                "  \\/ VoteAliasPathNext",
                "  \\/ FallbackPathNext",
                "VoteAliasPathNext == Guard => Interleaving!ImportedAction",
                "FallbackPathNext ==",
                *(f"  \\/ {action}" for action in top_actions),
            ],
        ),
        encoding="utf-8",
    )
    top_identity = tmp_path / "SumeragiIdentityModuleAliasHelperMixedActionNext.tla"
