    top = tmp_path / "SumeragiFalseGatedFairActionDisjunct.tla"
    top.write_text(
        commit_progress_spec_contract_text(
            spec_operator=top_spec,
            fairness_operator=top_fairness,
            next_closure=top_next_closure,
            fairness_actions=top_actions,
            next_lines=[
                f"Interleaving == INSTANCE {top_target_name}",
                f"{top_next_operator} ==",
                "  \\/ FALSE",
                f"  \\/ Interleaving!{top_action}",
                *(f"  \\/ {action}" for action in top_actions if action != top_action),
            ],
            action_definition_overrides={
                top_action: f"{top_action} == Interleaving!{top_action}",
            },
        ),
        encoding="utf-8",
    )

    source_next_line = module.tla_operator_signatures(source)[source_next_operator][0]
    top_next_line = module.tla_operator_signatures(top)[top_next_operator][0]
    assert module.source_commit_progress_spec_contract_errors(
        (
            (
                source,
                source_spec,
                source_fairness,
                source_next_closure,
                source_actions,
                source_root_kind,
            ),
        )
    ) == [
        f"{source}:{source_next_line} defines {source_root_kind} transition "
        f"operator {source_next_operator}, but direct transition disjunct "
        f"FALSE does not resolve to a named action-shaped operator; "
        f"{source_root_kind} transition disjuncts must resolve to named "
        "zero-arity action-shaped operators"
    ]
    assert module.top_level_commit_spec_contract_errors(
        (
            (
                top,
                top_spec,
                top_fairness,
                top_next_closure,
                top_actions,
                top_root_kind,
            ),
        )
    ) == [
        f"{top}:{top_next_line} defines {top_root_kind} transition operator "
        f"{top_next_operator}, but direct transition disjunct FALSE does not "
        f"resolve to a named action-shaped operator; {top_root_kind} "
        "transition disjuncts must resolve to named zero-arity action-shaped "
        "operators"
    ]


