def test_source_commit_progress_and_top_level_commit_spec_contract_errors_reject_false_gated_identity_gated_module_alias_next_disjunct_imported_fair_action_target_body_module_alias_helper_aggregate_branch_variants(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()

    def write_spec(
        role: str,
        target_name: str,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
        action: str,
    ) -> Path:
        next_operator = next_operator_from_closure(next_closure)
        other_actions = tuple(
            fair_action for fair_action in fairness_actions if fair_action != action
        )
        tla = tmp_path / f"Sumeragi{role}{target_name}Spec.tla"
        tla.write_text(
            commit_progress_spec_contract_text(
                spec_operator=spec_operator,
                fairness_operator=fairness_operator,
                next_closure=next_closure,
                fairness_actions=fairness_actions,
                preamble_lines=[f"Interleaving == INSTANCE {target_name}"],
                next_lines=[
                    f"{next_operator} ==",
                    "  \\/ FALSE",
                    f"  \\/ TRUE /\\ Interleaving!{action}",
                    *(f"  \\/ {fair_action}" for fair_action in other_actions),
                ],
                action_definition_overrides={
                    action: f"{action} == Interleaving!{action}",
                },
            ),
            encoding="utf-8",
        )
        return tla

    def fairness_action_line(tla: Path, action: str) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if f"WF_vars({action})" in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {action}")

    def branch_error(
        inner: Path,
        helper_line: int,
        root_kind: str,
        disjunct: str,
        kind: str,
    ) -> str:
        prefix = (
            f"{inner}:{helper_line} defines {root_kind} transition operator "
            f"HiddenAggregate, but direct transition disjunct {disjunct} "
        )
        if kind == "static":
            return (
                f"{prefix}does not resolve to a named action-shaped operator; "
                f"{root_kind} transition disjuncts must resolve to named "
                "zero-arity action-shaped operators"
            )
        return (
            f"{prefix}contains fairness or temporal syntax; {root_kind} "
            "transition disjuncts must stay single-branch action predicates"
        )

    def assert_module_alias_helper_aggregate_branch_case(
        role: str,
        suffix: str,
        use_mid: bool,
        inner_lines: list[str],
        expected_branches: list[tuple[str, str]],
        errors_fn,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
        root_kind: str,
    ) -> None:
        action = fairness_actions[0]
        inner = (
            tmp_path
            / f"SumeragiFalseGatedIdentity{role}FairAction{suffix}AggregateBranchInner.tla"
        )
        inner.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentity{role}FairAction{suffix}AggregateBranchInner ----",
                    "VARIABLES vars",
                    *inner_lines,
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        if use_mid:
            mid = (
                tmp_path
                / f"SumeragiFalseGatedIdentity{role}FairAction{suffix}AggregateBranchMid.tla"
            )
            mid.write_text(
                "\n".join(
                    [
                        f"---- MODULE SumeragiFalseGatedIdentity{role}FairAction{suffix}AggregateBranchMid ----",
                        "VARIABLES vars",
                        f"Inner == INSTANCE {inner.stem}",
                        "MidHelper == Inner!HiddenAggregate",
                        "====",
                    ]
                ),
                encoding="utf-8",
            )
            target_lines = [
                f"Mid == INSTANCE {mid.stem}",
                f"{action} == HiddenHelper",
                "HiddenHelper == Mid!MidHelper",
            ]
        else:
            target_lines = [
                f"Inner == INSTANCE {inner.stem}",
                f"{action} == HiddenHelper",
                "HiddenHelper == Inner!HiddenAggregate",
            ]
        target = (
            tmp_path
            / f"SumeragiFalseGatedIdentity{role}FairAction{suffix}AggregateBranchTarget.tla"
        )
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentity{role}FairAction{suffix}AggregateBranchTarget ----",
                    "VARIABLES vars",
                    *target_lines,
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        tla = write_spec(
            role,
            target.stem,
            spec_operator,
            fairness_operator,
            next_closure,
            fairness_actions,
            action,
        )
        inner_definitions = module.tla_single_expression_operator_definitions(inner)
        target_signatures = module.tla_operator_signatures(target)
        definitions = module.tla_single_expression_operator_definitions(tla)
        signatures = module.tla_operator_signatures(tla)
        target_line = target_signatures[action][0]
        helper_line = inner_definitions["HiddenAggregate"][0]
        fairness_line = definitions[fairness_operator][0]
        action_line = signatures[action][0]
        wf_line = fairness_action_line(tla, action)
        assert errors_fn(
            (
                (
                    tla,
                    spec_operator,
                    fairness_operator,
                    next_closure,
                    fairness_actions,
                    root_kind,
                ),
            )
        ) == [
            *[
                branch_error(inner, helper_line, root_kind, disjunct, kind)
                for disjunct, kind in expected_branches
            ],
            f"{tla}:{fairness_line} defines {fairness_operator}, but "
            f"references WF_vars action {action} at line {wf_line} whose "
            f"definition at line {action_line} aliases Interleaving!{action}, "
            f"but target {target}:{target_line} is not action-shaped; "
            f"{root_kind} fairness action aliases must resolve to transition "
            "definitions that mention next-state updates or UNCHANGED",
        ]

    cases = (
        (
            "AllStatic",
            ["HiddenAggregate == UNCHANGED vars \\/ TRUE"],
            [("UNCHANGED vars", "static"), ("TRUE", "static")],
        ),
        (
            "ActionStatic",
            [
                "HiddenAggregate == UNCHANGED vars \\/ HiddenReady",
                "HiddenReady == UNCHANGED vars",
            ],
            [("UNCHANGED vars", "static")],
        ),
        (
            "StaticTemporal",
            [
                "HiddenAggregate == UNCHANGED vars \\/ WF_vars(HiddenReady)",
                "HiddenReady == UNCHANGED vars",
            ],
            [("UNCHANGED vars", "static"), ("WF_vars(HiddenReady)", "temporal")],
        ),
    )

    (
        _source_module_path,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    ) = module.SUMERAGI_SOURCE_COMMIT_PROGRESS_SPEC_CONTRACTS[0]
    for alias_suffix, use_mid in (("ModuleAlias", False), ("MultiHopModuleAlias", True)):
        for case_suffix, inner_lines, expected_branches in cases:
            assert_module_alias_helper_aggregate_branch_case(
                "Source",
                f"{alias_suffix}{case_suffix}",
                use_mid,
                inner_lines,
                expected_branches,
                module.source_commit_progress_spec_contract_errors,
                source_spec,
                source_fairness,
                source_next_closure,
                source_actions,
                source_root_kind,
            )

    (
        _top_module_path,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    ) = module.SUMERAGI_TOP_LEVEL_COMMIT_SPEC_CONTRACTS[0]
    for alias_suffix, use_mid in (("ModuleAlias", False), ("MultiHopModuleAlias", True)):
        for case_suffix, inner_lines, expected_branches in cases:
            assert_module_alias_helper_aggregate_branch_case(
                "Top",
                f"{alias_suffix}{case_suffix}",
                use_mid,
                inner_lines,
                expected_branches,
                module.top_level_commit_spec_contract_errors,
                top_spec,
                top_fairness,
                top_next_closure,
                top_actions,
                top_root_kind,
            )


