def test_source_commit_progress_and_top_level_commit_spec_contract_errors_reject_false_gated_identity_gated_module_alias_next_disjunct_imported_fair_action_target_body_module_alias_helper_multi_hop_recursive_helper_bad_targets(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()

    def write_spec(
        role: str,
        target_name: str,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
        action: str,
    ) -> Path:
        next_operator = next_operator_from_closure(next_closure)
        other_actions = tuple(
            fair_action for fair_action in fairness_actions if fair_action != action
        )
        tla = (
            tmp_path
            / f"Sumeragi{role}FalseGatedIdentityFairActionHelperAliasMultiHopBadTarget.tla"
        )
        tla.write_text(
            commit_progress_spec_contract_text(
                spec_operator=spec_operator,
                fairness_operator=fairness_operator,
                next_closure=next_closure,
                fairness_actions=fairness_actions,
                preamble_lines=[f"Interleaving == INSTANCE {target_name}"],
                next_lines=[
                    f"{next_operator} ==",
                    "  \\/ FALSE",
                    f"  \\/ TRUE /\\ Interleaving!{action}",
                    *(f"  \\/ {fair_action}" for fair_action in other_actions),
                ],
                action_definition_overrides={
                    action: f"{action} == Interleaving!{action}",
                },
            ),
            encoding="utf-8",
        )
        return tla

    def fairness_action_line(tla: Path, action: str) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if f"WF_vars({action})" in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {action}")

    def assert_multi_hop_bad_targets_case(
        role: str,
        errors_fn,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
        root_kind: str,
    ) -> None:
        action = fairness_actions[0]
        inner = (
            tmp_path
            / f"SumeragiFalseGatedIdentity{role}FairActionHelperAliasMultiHopBadInner.tla"
        )
        inner.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentity{role}FairActionHelperAliasMultiHopBadInner ----",
                    "VARIABLES vars",
                    "Branch == LocalBranch",
                    "LocalBranch == ParameterizedHelper /\\ OpaqueHelper",
                    "ParameterizedHelper(peer) == UNCHANGED vars",
                    "OpaqueHelper ==",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        target = (
            tmp_path
            / f"SumeragiFalseGatedIdentity{role}FairActionHelperAliasMultiHopBadTarget.tla"
        )
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentity{role}FairActionHelperAliasMultiHopBadTarget ----",
                    "VARIABLES vars",
                    f"Inner == INSTANCE {inner.stem}",
                    f"{action} == HiddenHelper",
                    "HiddenHelper == Start",
                    "Start == Inner!Branch",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        tla = write_spec(
            role,
            target.stem,
            spec_operator,
            fairness_operator,
            next_closure,
            fairness_actions,
            action,
        )

        inner_signatures = module.tla_operator_signatures(inner)
        target_signatures = module.tla_operator_signatures(target)
        definitions = module.tla_single_expression_operator_definitions(tla)
        signatures = module.tla_operator_signatures(tla)
        branch_line = inner_signatures["Branch"][0]
        parameterized_line = inner_signatures["ParameterizedHelper"][0]
        opaque_line = inner_signatures["OpaqueHelper"][0]
        target_line = target_signatures[action][0]
        fairness_line = definitions[fairness_operator][0]
        action_line = signatures[action][0]
        wf_line = fairness_action_line(tla, action)
        assert errors_fn(
            (
                (
                    tla,
                    spec_operator,
                    fairness_operator,
                    next_closure,
                    fairness_actions,
                    root_kind,
                ),
            )
        ) == [
            f"{inner}:{branch_line} defines {root_kind} transition operator "
            "Branch, but direct transition disjunct LocalBranch does not "
            f"resolve to a named action-shaped operator; {root_kind} "
            "transition disjuncts must resolve to named zero-arity "
            "action-shaped operators",
            f"{tla}:{fairness_line} defines {fairness_operator}, but "
            f"references WF_vars action {action} at line {wf_line} whose "
            f"definition at line {action_line} aliases Interleaving!{action}, "
            f"but target {target}:{target_line} reaches helper "
            f"ParameterizedHelper at {inner}:{parameterized_line}, but helper "
            f"has arity 1; {root_kind} fairness action aliases must resolve "
            "helper-alias helper references to defined zero-arity helper "
            "definitions",
            f"{tla}:{fairness_line} defines {fairness_operator}, but "
            f"references WF_vars action {action} at line {wf_line} whose "
            f"definition at line {action_line} aliases Interleaving!{action}, "
            f"but target {target}:{target_line} reaches helper OpaqueHelper "
            f"at {inner}:{opaque_line}, but helper is not an inspectable "
            f"single-expression definition; {root_kind} fairness action "
            "aliases must resolve helper-alias helper references to "
            "inspectable helper definitions",
            f"{tla}:{fairness_line} defines {fairness_operator}, but "
            f"references WF_vars action {action} at line {wf_line} whose "
            f"definition at line {action_line} aliases Interleaving!{action}, "
            f"but target {target}:{target_line} is not action-shaped; "
            f"{root_kind} fairness action aliases must resolve to transition "
            "definitions that mention next-state updates or UNCHANGED",
        ]

    (
        _source_module_path,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    ) = module.SUMERAGI_SOURCE_COMMIT_PROGRESS_SPEC_CONTRACTS[0]
    assert_multi_hop_bad_targets_case(
        "Source",
        module.source_commit_progress_spec_contract_errors,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    )

    (
        _top_module_path,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    ) = module.SUMERAGI_TOP_LEVEL_COMMIT_SPEC_CONTRACTS[0]
    assert_multi_hop_bad_targets_case(
        "Top",
        module.top_level_commit_spec_contract_errors,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    )


