        other_actions = tuple(
            fair_action for fair_action in fairness_actions if fair_action != action
        )
        tla = (
            tmp_path
            / f"Sumeragi{role}FalseGatedIdentityFairActionHelperAliasTransitiveFairActionTarget.tla"
        )
