def test_source_commit_progress_and_top_level_commit_spec_contract_errors_reject_false_gated_identity_gated_module_alias_next_disjunct_imported_fair_action_alias_multi_hop_cycles(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()

    def write_spec(
        role: str,
        target_name: str,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
        action: str,
    ) -> Path:
        next_operator = next_operator_from_closure(next_closure)
        other_actions = tuple(
            fair_action for fair_action in fairness_actions if fair_action != action
        )
        tla = (
            tmp_path
            / f"Sumeragi{role}FalseGatedIdentityFairActionAliasMultiHopCycle.tla"
        )
        tla.write_text(
            commit_progress_spec_contract_text(
                spec_operator=spec_operator,
                fairness_operator=fairness_operator,
                next_closure=next_closure,
                fairness_actions=fairness_actions,
                preamble_lines=[f"Interleaving == INSTANCE {target_name}"],
                next_lines=[
                    f"{next_operator} ==",
                    "  \\/ FALSE",
                    f"  \\/ TRUE /\\ Interleaving!{action}",
                    *(f"  \\/ {fair_action}" for fair_action in other_actions),
                ],
                action_definition_overrides={
                    action: f"{action} == Interleaving!{action}",
                },
            ),
            encoding="utf-8",
        )
        return tla

    def fairness_action_line(tla: Path, action: str) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if f"WF_vars({action})" in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {action}")

    def assert_alias_multi_hop_cycle_case(
        role: str,
        errors_fn,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
        root_kind: str,
    ) -> None:
        action = fairness_actions[0]
        target = (
            tmp_path
            / f"SumeragiFalseGatedIdentity{role}FairActionAliasMultiHopCycleTarget.tla"
        )
        inner = (
            tmp_path
            / f"SumeragiFalseGatedIdentity{role}FairActionAliasMultiHopCycleInner.tla"
        )
        leaf = (
            tmp_path
            / f"SumeragiFalseGatedIdentity{role}FairActionAliasMultiHopCycleLeaf.tla"
        )
        target.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentity{role}FairActionAliasMultiHopCycleTarget ----",
                    "VARIABLES vars",
                    f"Inner == INSTANCE {inner.stem}",
                    f"{action} == Inner!Start",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        inner.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentity{role}FairActionAliasMultiHopCycleInner ----",
                    "VARIABLES vars",
                    f"Leaf == INSTANCE {leaf.stem}",
                    "Start == Leaf!Branch",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        leaf.write_text(
            "\n".join(
                [
                    f"---- MODULE SumeragiFalseGatedIdentity{role}FairActionAliasMultiHopCycleLeaf ----",
                    "VARIABLES vars",
                    f"Back == INSTANCE {target.stem}",
                    f"Branch == Back!{action}",
                    "====",
                ]
            ),
            encoding="utf-8",
        )
        tla = write_spec(
            role,
            target.stem,
            spec_operator,
            fairness_operator,
            next_closure,
            fairness_actions,
            action,
        )

        definitions = module.tla_single_expression_operator_definitions(tla)
        signatures = module.tla_operator_signatures(tla)
        target_definitions = module.tla_single_expression_operator_definitions(target)
        fairness_line = definitions[fairness_operator][0]
        action_line = signatures[action][0]
        target_line = target_definitions[action][0]
        wf_line = fairness_action_line(tla, action)
        assert errors_fn(
            (
                (
                    tla,
                    spec_operator,
                    fairness_operator,
                    next_closure,
                    fairness_actions,
                    root_kind,
                ),
            )
        ) == [
            f"{target}:{target_line} defines {root_kind} transition helper "
            f"{action}, but transition helper resolution cycles at {action}; "
            f"{root_kind} transition helper wrappers must be acyclic and "
            "resolve to inspectable transition operators",
            f"{target}:{target_line} defines {root_kind} transition operator "
            f"{action}, but transition alias resolution cycles at {action}; "
            f"{root_kind} transition aliases must be acyclic and resolve to "
            "inspectable transition operators",
            f"{tla}:{fairness_line} defines {fairness_operator}, but "
            f"references WF_vars action {action} at line {wf_line} whose "
            f"definition at line {action_line} aliases Interleaving!{action}, "
            f"but fairness action alias resolution cycles at {target}:"
            f"{target_line} {action}; {root_kind} fairness action aliases "
            "must be acyclic and resolve to inspectable transition definitions",
        ]

    (
        _source_module_path,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    ) = module.SUMERAGI_SOURCE_COMMIT_PROGRESS_SPEC_CONTRACTS[2]
    assert_alias_multi_hop_cycle_case(
        "Source",
        module.source_commit_progress_spec_contract_errors,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    )

    (
        _top_module_path,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    ) = module.SUMERAGI_TOP_LEVEL_COMMIT_SPEC_CONTRACTS[0]
    assert_alias_multi_hop_cycle_case(
        "Top",
        module.top_level_commit_spec_contract_errors,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    )


def test_source_commit_progress_and_top_level_commit_spec_contract_errors_reject_false_gated_module_alias_next_disjunct_imported_fair_action_malformed_target(
    tmp_path: Path,
) -> None:
    module = load_coverage_module()

    def write_target(
        target_name: str,
        lines: list[str] | None,
    ) -> Path:
        target = tmp_path / f"{target_name}.tla"
        if lines is not None:
            target.write_text(
                "\n".join(
                    [
                        f"---- MODULE {target_name} ----",
                        "VARIABLES vars",
                        *lines,
                        "====",
                    ]
                ),
                encoding="utf-8",
            )
        return target

    def write_spec(
        role: str,
        case_name: str,
        target_name: str,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
        action: str,
    ) -> Path:
        next_operator = next_operator_from_closure(next_closure)
        other_actions = tuple(
            fair_action for fair_action in fairness_actions if fair_action != action
        )
        tla = tmp_path / f"Sumeragi{role}FalseGatedFairAction{case_name}.tla"
        tla.write_text(
            commit_progress_spec_contract_text(
                spec_operator=spec_operator,
                fairness_operator=fairness_operator,
                next_closure=next_closure,
                fairness_actions=fairness_actions,
                preamble_lines=[f"Interleaving == INSTANCE {target_name}"],
                next_lines=[
                    f"{next_operator} ==",
                    "  \\/ FALSE",
                    f"  \\/ Interleaving!{action}",
                    *(f"  \\/ {fair_action}" for fair_action in other_actions),
                ],
                action_definition_overrides={
                    action: f"{action} == Interleaving!{action}",
                },
            ),
            encoding="utf-8",
        )
        return tla

    def fairness_action_line(tla: Path, action: str) -> int:
        for line_number, line in enumerate(
            tla.read_text(encoding="utf-8").splitlines(),
            1,
        ):
            if f"WF_vars({action})" in line:
                return line_number
        raise AssertionError(f"missing WF_vars line for {action}")

    def expected_errors(
        tla: Path,
        target_problem: str,
        next_operator: str,
        next_closure: str,
        fairness_operator: str,
        action: str,
        root_kind: str,
        disjunct_requirement: str,
        fairness_requirement: str,
        *,
        include_reachability_error: bool = False,
    ) -> list[str]:
        signatures = module.tla_operator_signatures(tla)
        definitions = module.tla_single_expression_operator_definitions(tla)
        next_line = signatures[next_operator][0]
        fairness_line = definitions[fairness_operator][0]
        action_line = signatures[action][0]
        wf_line = fairness_action_line(tla, action)
        errors = [
            f"{tla}:{next_line} defines {root_kind} transition operator "
            f"{next_operator}, but direct transition disjunct "
            f"Interleaving!{action} aliases Interleaving!{action}, but "
            f"{target_problem}; {root_kind} transition module-alias "
            f"disjuncts must resolve to {disjunct_requirement}",
        ]
        if include_reachability_error:
            errors.append(
                f"{tla}:{next_line} defines {root_kind} transition operator "
                f"{next_operator}, but {next_closure} cannot reach fair "
                f"action(s) {action}; {root_kind} fairness actions must be "
                "reachable from the checked transition closure"
            )
        errors.append(
            f"{tla}:{fairness_line} defines {fairness_operator}, but "
            f"references WF_vars action {action} at line {wf_line} whose "
            f"definition at line {action_line} aliases Interleaving!{action}, "
            f"but {target_problem}; {root_kind} fairness action aliases must "
            f"resolve to {fairness_requirement}",
        )
        return errors

    def assert_malformed_target_cases(
        role: str,
        errors_fn,
        spec_operator: str,
        fairness_operator: str,
        next_closure: str,
        fairness_actions: tuple[str, ...],
        root_kind: str,
    ) -> None:
        action = fairness_actions[0]
        next_operator = next_operator_from_closure(next_closure)

        def assert_case(
            case_name: str,
            target_lines: list[str] | None,
            target_problem,
            disjunct_requirement: str,
            fairness_requirement: str,
        ) -> None:
            target_name = f"SumeragiFalseGated{role}FairAction{case_name}Target"
            target = write_target(target_name, target_lines)
            tla = write_spec(
                role,
                case_name,
                target_name,
                spec_operator,
                fairness_operator,
                next_closure,
                fairness_actions,
                action,
            )
            assert errors_fn(
                (
                    (
                        tla,
                        spec_operator,
                        fairness_operator,
                        next_closure,
                        fairness_actions,
                        root_kind,
                    ),
                )
            ) == expected_errors(
                tla,
                target_problem(target, action),
                next_operator,
                next_closure,
                fairness_operator,
                action,
                root_kind,
                disjunct_requirement,
                fairness_requirement,
                include_reachability_error=target_lines is None,
            )

        assert_case(
            "Missing",
            None,
            lambda target, _action: f"target module {target} does not exist",
            "local modules with defined zero-arity transition operators",
            "local action modules",
        )
        assert_case(
            "Undefined",
            ["Other == UNCHANGED vars"],
            lambda target, action: f"target {target} does not define {action}",
            "defined zero-arity transition operators",
            "defined zero-arity actions",
        )
        assert_case(
            "Parameterized",
            [f"{action}(value) == UNCHANGED vars"],
            lambda target, action: (
                f"target {target}:"
                f"{module.tla_operator_signatures(target)[action][0]} has arity 1"
            ),
            "defined zero-arity transition operators",
            "defined zero-arity actions",
        )
        assert_case(
            "Noninspectable",
            [f"{action} =="],
            lambda target, action: (
                f"target {target}:"
                f"{module.tla_operator_signatures(target)[action][0]} is not "
                "an inspectable single-expression definition"
            ),
            "inspectable transition operators",
            "inspectable actions",
        )

    (
        _source_module_path,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    ) = module.SUMERAGI_SOURCE_COMMIT_PROGRESS_SPEC_CONTRACTS[0]
    assert_malformed_target_cases(
        "Source",
        module.source_commit_progress_spec_contract_errors,
        source_spec,
        source_fairness,
        source_next_closure,
        source_actions,
        source_root_kind,
    )

    (
        _top_module_path,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    ) = module.SUMERAGI_TOP_LEVEL_COMMIT_SPEC_CONTRACTS[0]
    assert_malformed_target_cases(
        "Top",
        module.top_level_commit_spec_contract_errors,
        top_spec,
        top_fairness,
        top_next_closure,
        top_actions,
        top_root_kind,
    )


